UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"The agent has no bounded business purpose, so new prompts, tools or integrations silently broaden what it may do.","customer_symptom":"A user or operator may observe the agent has no bounded business purpose, so new prompts, tools or integrations silently broaden what it may do; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"an external content author, compromised source, malicious user, or unsafe model output can exploit or trigger the condition in the agent has no bounded business purpose, so new prompts, tools or integrations silently broaden what it may do, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","tool endpoints and downstream systems","financial, administrative or state-changing actions","agent","model context"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["all agents"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"The test crosses the boundary between all agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If the agent has no bounded business purpose, so new prompts, tools or integrations silently broaden what it may do, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-08-05","next_review_due":"2026-11-03","change_triggers":["ARL-KB-001 control or enforcement change","ARL-KB-001 model, prompt, tool, identity, data-source or provider change","ARL-KB-001 bypass, incident or new attack evidence","ARL-KB-001 evidence expiry or material scope change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='1614736dbfbf3086d3afef594d122604506c72a244f053d2b9c0aa5dda3c88de', updated_at='2026-08-06' WHERE id='ARL-KB-001';
UPDATE risk_knowledge_checks SET objective='Determine whether the assessed system prevents or detects: agent purpose is undefined or expands without approval.', method='Compare the declared purpose, production prompts, tool catalogue and recent change history; flag capabilities that are not necessary for an approved use case. Review the exact assessed version against the approved governance record for “Agent purpose is undefined or expands without approval”; compare the declared purpose, permitted and prohibited outcomes, prompts, tools, integrations and recent change history, and require explicit approval for any material scope expansion.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-001 assessed system, version, environment and scope","ARL-KB-001 versioned business purpose, permitted outcomes and prohibited outcomes","ARL-KB-001 production prompt or equivalent governing instructions and current tool/integration catalogue","ARL-KB-001 recent material change history and approvals for scope-expanding changes","ARL-KB-001 reviewer identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-001 passes only when the exact assessed version has a bounded, versioned and accountable purpose; current prompts, tools, integrations and data access are necessary for that approved purpose or explicitly approved as scope changes; and version-bound evidence records the reviewer, timestamp and digest.', fail_condition='ARL-KB-001 fails when the agent has no bounded business purpose, so new prompts, tools or integrations silently broaden what it may do, when a current capability cannot be justified by the approved purpose, when a material scope expansion lacks accountable approval, or when the conclusion is unsupported by version-bound review evidence.', limitations='This bounded ARL-KB-001 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='6a4c63b510c1e1ee5808fa97ba294a524491ca009c822f2d58a55548fcc51bf9', updated_at='2026-08-06' WHERE entry_id='ARL-KB-001';
UPDATE risk_knowledge_solutions SET control_objective='Ensure the agent has a versioned, accountable and bounded purpose, with explicit permitted and prohibited outcomes, and prevent material expansion of capabilities, authority, data access or integrations without documented human approval.', recommended_remediation='Record and approve a versioned agent purpose, permitted outcomes, prohibited outcomes, accountable owner and material scope boundaries. Require an attributable change record and accountable human approval before expanding prompts, tools, integrations, data access, network reach or execution authority.', default_owner='Product owner', priority='P1', implementation_principles_json='["ARL-KB-001: the approved agent purpose and scope must be explicit, versioned and attributable.","ARL-KB-001: each material capability must be necessary for the approved purpose or covered by an approved scope-change record.","ARL-KB-001: permitted and prohibited outcomes must remain visible to operators and reviewers.","ARL-KB-001: material expansion of prompts, tools, integrations, data access, network reach or authority requires accountable human review before it becomes approved scope."]', monitoring='For ARL-KB-001, monitor changes to the versioned purpose, permitted and prohibited outcomes, prompts, tools, integrations, data destinations and authority boundaries. Record the exact version, change author, reviewer, approval decision and evidence digest for material scope changes.', containment='If an undeclared or unapproved capability is identified, treat it as outside the approved scope, prevent it from being accepted as an authorised capability, preserve the relevant version and change evidence, and require accountable review before the scope is expanded or the capability is accepted.', retest_acceptance_json='["ARL-KB-001: The exact remediated version has an explicit, versioned and attributable purpose.","ARL-KB-001: Permitted and prohibited outcomes are documented and consistent with the assessed capabilities.","ARL-KB-001: Every material prompt, tool, integration, data-access or authority capability is necessary for the approved purpose or has an attributable approved scope-change record.","ARL-KB-001: A proposed material scope expansion cannot be treated as approved without the required accountable human decision.","ARL-KB-001: Reviewer identity, timestamp, assessed version, evidence digest, known limitations and scope decision are recorded."]', content_digest='94be9ff5da084e8c5ef74a988de5872948af6a439b33baa7ca4dc2e8545a9249', updated_at='2026-08-06' WHERE entry_id='ARL-KB-001';
UPDATE risk_knowledge_operational_metadata SET automation_status='unsupported', customer_validation_status='unvalidated', content_digest='ccaadb47c6c2dbad8abac9360350851f66442c4d9eda19fc01d352d924443857', updated_at='2026-08-06' WHERE entry_id='ARL-KB-001';
INSERT INTO risk_knowledge_validation_records (id,entry_id,lifecycle_status,knowledge_version,created_at) VALUES ('rkv_001','ARL-KB-001','candidate','ARL-RKA-1.2.0','2026-08-06') ON CONFLICT(entry_id,knowledge_version) DO NOTHING;
INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-001','high','active','2026-08-05','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"No named person is responsible for accepting residual risk, funding remediation or stopping deployment.","customer_symptom":"Operators cannot identify who is accountable for accepting residual risk, authorising remediation or stopping deployment, so material security decisions may remain unresolved, be made informally, or be attributed to someone without the required authority.","credible_failure_or_attack":"governance failure can leave a material risk, unresolved finding or deployment decision without a named accountable human who has documented authority to accept residual risk, authorise remediation or stop or withhold deployment.","affected_assets":["residual-risk decisions","remediation funding and authorisation","deployment and readiness decisions","security findings and exceptions","assessment evidence and governance records","accountability and escalation paths"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["all agents"],"threat_actor_or_failure_source":"missing ownership, ambiguous responsibility, expired appointment, incomplete delegation or unsupported decision authority","trust_boundary":"The control governs the boundary between technical assessment evidence and the human governance authority responsible for accepting risk, authorising remediation and stopping or withholding deployment.","operational_impact":"Without an accountable risk owner, critical findings, remediation funding, residual-risk acceptance and deployment holds may have no authorised decision-maker, causing unresolved risk, delayed response or unsupported deployment decisions."}', review_json='{"human_review_required":true,"last_reviewed":"2026-08-05","next_review_due":"2026-11-03","change_triggers":["ARL-KB-002 control or enforcement change","ARL-KB-002 model, prompt, tool, identity, data-source or provider change","ARL-KB-002 bypass, incident or new attack evidence","ARL-KB-002 evidence expiry or material scope change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='11db8602b7874cd5f4b81cb7e07e9f199f2b6f1ca9d4a7e39cc550ea04814e3f', updated_at='2026-08-06' WHERE id='ARL-KB-002';
UPDATE risk_knowledge_checks SET objective='Determine whether the exact assessed system and scope have a named, current and attributable human risk owner with documented authority for residual-risk acceptance, remediation authorisation and deployment withholding.', method='Identify the exact assessed system, version, environment and scope. Inspect the current risk-owner appointment, governance record or equivalent authoritative evidence. Verify that a named accountable risk owner is assigned to the assessed system and scope, that the appointment is current, attributable and not expired, and that the documented authority includes the ability to accept residual risk, fund or authorise remediation, and stop or withhold deployment. Where delegation exists, verify its scope, authority, effective date and expiry. Record the reviewer, timestamp and evidence digest.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-002 assessed system, version, environment and scope","ARL-KB-002 named accountable risk owner and role","ARL-KB-002 documented authority for residual-risk acceptance, remediation funding or authorisation, and deployment stop or withholding","ARL-KB-002 owner appointment, delegation or approval record with effective date and expiry where applicable","ARL-KB-002 reviewer identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-002 passes only when the exact assessed system and scope have a named accountable risk owner with documented authority to accept residual risk, fund or authorise remediation, and stop or withhold deployment; the ownership record is current and attributable; and version-bound evidence records the reviewer, timestamp and digest.', fail_condition='ARL-KB-002 fails when no named person is responsible for accepting residual risk, funding remediation or stopping deployment, when ownership is unnamed, expired or not bound to the assessed system and scope, when any required authority is absent or unsupported, or when the conclusion lacks version-bound review evidence.', limitations='This review verifies documented ownership and authority for the assessed system and scope. It does not prove how the named person would exercise that authority in every future incident or decision.', content_digest='0e402e9bc47bf4f2b24bfb557e3924938139ebac0343dcd1e542a301f5dd6a9e', updated_at='2026-08-06' WHERE entry_id='ARL-KB-002';
UPDATE risk_knowledge_solutions SET control_objective='Ensure every assessed agent has a named and accountable human risk owner with documented authority to accept residual risk, authorise or fund remediation, and stop or withhold deployment.', recommended_remediation='Appoint a named accountable risk owner for the exact assessed system and scope. Document the owner''s role, contact, effective date, expiry where applicable, and explicit authority for residual-risk acceptance, remediation funding or authorisation, and deployment stop or withholding. Define deputies or delegation only where their authority and scope are explicitly recorded.', default_owner='Executive risk owner', priority='P1', implementation_principles_json='["ARL-KB-002: accountability must be assigned to a named human, not an unnamed team, model or automated system.","ARL-KB-002: the owner record must be bound to the assessed system and scope.","ARL-KB-002: residual-risk acceptance, remediation authority and deployment-withholding authority must be explicit.","ARL-KB-002: appointment, delegation and expiry must be attributable and reviewable."]', monitoring='For ARL-KB-002, monitor ownership changes, role changes, delegation, expiry and loss of required authority. Record the current owner, assessed scope, effective date, reviewer and evidence digest whenever ownership evidence changes.', containment='If the accountable risk owner is missing, expired, unnamed or lacks a required authority, place affected residual-risk or deployment decisions on hold until a valid owner or authorised delegate is formally recorded.', retest_acceptance_json='["ARL-KB-002: A named accountable risk owner is recorded for the exact assessed system and scope.","ARL-KB-002: Residual-risk acceptance, remediation funding or authorisation, and deployment stop or withholding authorities are explicitly documented.","ARL-KB-002: Appointment and delegation records are current, attributable and not expired.","ARL-KB-002: Missing, expired, unnamed or incomplete ownership evidence results in hold or review rather than control satisfaction.","ARL-KB-002: Reviewer identity, assessed version, timestamp and evidence digest are recorded."]', content_digest='e7969fb9ad87414e93acf3c1224428c98c4c9faeb4590d4e1b81f8f7bf763bf9', updated_at='2026-08-06' WHERE entry_id='ARL-KB-002';
UPDATE risk_knowledge_operational_metadata SET automation_status='unsupported', customer_validation_status='unvalidated', content_digest='029af4579d0ad1a3897abc1fb269fc9f1b5643ec36bc545d850f2e793f70a351', updated_at='2026-08-06' WHERE entry_id='ARL-KB-002';
INSERT INTO risk_knowledge_validation_records (id,entry_id,lifecycle_status,knowledge_version,created_at) VALUES ('rkv_002','ARL-KB-002','candidate','ARL-RKA-1.2.0','2026-08-06') ON CONFLICT(entry_id,knowledge_version) DO NOTHING;
INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-002','high','active','2026-08-05','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"The organisation has not stated which users, decisions, sectors or actions the agent must never support.","customer_symptom":"Operators cannot determine which users, decisions, sectors, actions or outcomes the agent must never support, so prohibited or harmful behaviour may be treated as ordinary in-scope use.","credible_failure_or_attack":"a user, model, tool path or operator can request or trigger an action that falls inside a prohibited-use or harm boundary when those boundaries are absent, ambiguous, incomplete or not enforced before the consequential action.","affected_assets":["people, rights and safety affected by agent actions","regulated or otherwise prohibited activities","high-impact decisions and downstream actions","agent tools and execution authority","prohibited-use and harm-boundary policy","assessment and enforcement evidence"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["agents affecting people, rights, safety or regulated activity"],"threat_actor_or_failure_source":"missing or ambiguous prohibited-use rules, incomplete harm analysis, unsafe requests, model behaviour, tool execution or operator error","trust_boundary":"The control governs the boundary between an agent request or proposed action and the prohibited-use or harm rules that determine whether that activity may proceed, must be refused, or requires explicit human escalation.","operational_impact":"If prohibited uses and harm boundaries are undefined or unenforced, the agent may support an activity the organisation intended to forbid, potentially requiring immediate containment, investigation, human escalation and a hold on the affected capability."}', review_json='{"human_review_required":true,"last_reviewed":"2026-08-05","next_review_due":"2026-10-04","change_triggers":["ARL-KB-003 control or enforcement change","ARL-KB-003 model, prompt, tool, identity, data-source or provider change","ARL-KB-003 bypass, incident or new attack evidence","ARL-KB-003 evidence expiry or material scope change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='ca5240e23ed7b1b29c2b03a2dbc4bc75650c106863c3031da97ca52914488bc6', updated_at='2026-08-06' WHERE id='ARL-KB-003';
UPDATE risk_knowledge_checks SET objective='Determine whether relevant prohibited uses and harm boundaries are explicit, versioned and enforced for the exact assessed system and whether representative forbidden requests are refused or explicitly escalated before a prohibited material action occurs.', method='Identify the exact assessed system, version, environment and scope. Review the versioned prohibited-use and harm boundaries and determine which users, decisions, sectors, actions or outcomes are explicitly forbidden or require human escalation. Trace those boundaries to the relevant prompts, policy rules, tool restrictions or other enforcement points. Execute an authorised positive case and representative forbidden requests using safe non-production conditions. Verify that legitimate in-scope use remains available and that each prohibited case is refused or escalated before the prohibited material action occurs.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-003 assessed system, version, environment and scope","ARL-KB-003 versioned prohibited-use and harm-boundary policy","ARL-KB-003 governing prompt, policy or tool-enforcement locations implementing the prohibited boundaries","ARL-KB-003 authorised positive request and representative forbidden request with expected and observed results","ARL-KB-003 reviewer identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-003 passes only when the exact assessed version has explicit, versioned prohibited-use and harm boundaries covering the relevant users, decisions, sectors or actions; representative forbidden requests are refused or escalated before material side effects; authorised in-scope use remains available; and version-bound evidence records the reviewer, timestamp and digest.', fail_condition='ARL-KB-003 fails when the organisation has not stated which users, decisions, sectors or actions the agent must never support, when prohibited boundaries are ambiguous or unsupported, when a representative forbidden request can proceed to a material side effect, or when the conclusion lacks version-bound review evidence.', limitations='A bounded set of prohibited-use tests cannot prove that every possible harmful request or future bypass has been identified. The conclusion applies only to the documented boundaries, tested scenarios, exact assessed version and scope.', content_digest='c1c0a0b9b9cf10e0f1273f2cbab3df0fbfda665cd24e5d60da390f34096e1df4', updated_at='2026-08-06' WHERE entry_id='ARL-KB-003';
UPDATE risk_knowledge_solutions SET control_objective='Ensure relevant prohibited uses and harm boundaries are explicitly defined, versioned and enforced so prohibited agent activity is refused or routed to the required human decision before a prohibited material action occurs.', recommended_remediation='Define a versioned prohibited-use and harm-boundary policy covering relevant users, decisions, sectors, actions and outcomes. Map each material boundary to an enforceable control point, define refusal and escalation behaviour, assign an accountable owner, and test representative allowed and prohibited cases.', default_owner='Risk and compliance owner', priority='P0', implementation_principles_json='["ARL-KB-003: prohibited uses and harm boundaries must be explicit, versioned and attributable.","ARL-KB-003: prohibited boundaries must be enforced at a control point capable of preventing the material action, not only described in model instructions.","ARL-KB-003: legitimate in-scope activity should remain available while prohibited activity is refused or escalated.","ARL-KB-003: changes to prohibited boundaries or enforcement require accountable review and retest."]', monitoring='For ARL-KB-003, record prohibited-use policy version, assessed version, representative prohibited requests, resulting refusal or escalation decisions, enforcement point, reviewer and evidence digest. Review boundary changes, bypass attempts and enforcement drift.', containment='If a prohibited-use boundary is missing, ambiguous or bypassable, place the affected capability on hold or restrict it to a safe bounded mode until the boundary and enforcement path are corrected and retested.', retest_acceptance_json='["ARL-KB-003: The exact remediated version has explicit and versioned prohibited-use and harm boundaries relevant to its assessed scope.","ARL-KB-003: An authorised request outside the prohibited boundaries remains usable.","ARL-KB-003: Prohibited users, decisions, sectors or actions are denied before the prohibited material action occurs, or routed to the explicitly required human escalation.","ARL-KB-003: The tested boundary is traceable to an identified enforcement location.","ARL-KB-003: Reviewer identity, timestamp, assessed version, policy version and evidence digest are recorded."]', content_digest='67ec7b6f76a3a2bd446e8ba9c03a88a99f33de7ece64ccc79605216a11a33997', updated_at='2026-08-06' WHERE entry_id='ARL-KB-003';
UPDATE risk_knowledge_operational_metadata SET automation_status='unsupported', customer_validation_status='unvalidated', content_digest='a86362324f843d2c04f1a8d66342450cf79cef03d0855b37d9d6969ea2c09b73', updated_at='2026-08-06' WHERE entry_id='ARL-KB-003';
INSERT INTO risk_knowledge_validation_records (id,entry_id,lifecycle_status,knowledge_version,created_at) VALUES ('rkv_003','ARL-KB-003','candidate','ARL-RKA-1.2.0','2026-08-06') ON CONFLICT(entry_id,knowledge_version) DO NOTHING;
INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-003','critical','active','2026-08-05','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"The agent is treated as low risk even though it can move money, alter records, affect rights, disclose sensitive data or control infrastructure.","customer_symptom":"The system is governed as lower risk than its actual reachable capabilities justify, so controls, review depth, evidence requirements or deployment gates may be weaker than the maximum credible impact requires.","credible_failure_or_attack":"an incomplete or outdated risk classification can omit impact-relevant capabilities such as authority, sensitive-data access, irreversible actions, financial effects, effects on people or rights, infrastructure control, scale or downstream dependency chains, causing the declared risk tier to understate the system''s real maximum credible impact.","affected_assets":["risk classification and assurance requirements","people, rights and safety affected by agent actions","financial and state-changing actions","sensitive data and regulated information","infrastructure and downstream systems","deployment and residual-risk decisions"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["agents with tools or consequential outputs"],"threat_actor_or_failure_source":"incomplete capability inventory, outdated classification evidence, underestimated impact, configuration drift or human classification error","trust_boundary":"The control governs the boundary between the agent''s actual reachable authority and impact and the governance classification used to determine required controls, testing, evidence and deployment decisions.","operational_impact":"If the declared risk tier understates real impact, the system may receive weaker controls, testing or review than its capabilities require. The affected classification and deployment decision must remain on hold until impact is reassessed and an accountable human records the resulting tier."}', review_json='{"human_review_required":true,"last_reviewed":"2026-08-05","next_review_due":"2026-10-04","change_triggers":["ARL-KB-004 control or enforcement change","ARL-KB-004 model, prompt, tool, identity, data-source or provider change","ARL-KB-004 bypass, incident or new attack evidence","ARL-KB-004 evidence expiry or material scope change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='d747957f1f708f19a3c178023fb076c8783f16fa5410445c35999ad4bebe66a7', updated_at='2026-08-06' WHERE id='ARL-KB-004';
UPDATE risk_knowledge_checks SET objective='Determine whether the declared risk classification of the assessed system matches the maximum credible impact of its actual reachable capabilities.', method='Identify the exact assessed version and declared risk tier. Inventory the system''s reachable assets, identities, data, tools, integrations, permissions, maximum action values, reversibility, affected people, scale and dependency chains. Determine the maximum credible impact supported by observed evidence, then compare that impact with the declared risk tier. Any classification decision or reclassification must be made by an accountable human reviewer and recorded with version-bound evidence.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-004 exact assessed system, version, environment, scope and declared risk tier","ARL-KB-004 observed inventory of impact-relevant capabilities, including authority, reachable assets, data access, maximum action values, reversibility, scale, affected people and dependency chains","ARL-KB-004 documented comparison between the declared risk tier and the maximum credible observed impact, including classification rationale","ARL-KB-004 evidence for any capability or configuration materially affecting the impact classification","ARL-KB-004 accountable human reviewer identity, role, timestamp, decision and evidence digest"]', pass_condition='ARL-KB-004 passes only when the declared risk tier for the exact assessed version is supported by evidence of the system''s actual authority, reachable assets, data exposure, reversibility, scale, affected people and dependency chains; the declared tier is not lower than the tier required by the maximum credible observed impact; and the human reviewer, timestamp, rationale and evidence digest are recorded.', fail_condition='ARL-KB-004 fails when the declared risk tier understates the maximum credible impact of the system''s actual reachable capabilities, including the ability to move money, alter records, affect rights, disclose sensitive data, control infrastructure or cause material downstream effects; when impact-relevant capabilities are omitted from classification; or when the classification conclusion lacks accountable, version-bound human review evidence.', limitations='This review establishes the maximum credible impact supported by evidence for the exact assessed version and known reachable capabilities. It does not prove that no undiscovered capability or future architectural change could increase impact.', content_digest='f6b72f277d1a729edf58c57e543ec67355d02bc7d37846406a8d417c7654d9e2', updated_at='2026-08-06' WHERE entry_id='ARL-KB-004';
UPDATE risk_knowledge_solutions SET control_objective='Ensure the declared risk classification is not lower than the level required by the maximum credible impact of the agent''s actual reachable capabilities.', recommended_remediation='Reclassify the system using evidence of actual reachable authority, assets, data exposure, maximum action values, reversibility, scale, affected people and downstream dependency chains. Bind the resulting tier and rationale to the exact assessed version and require accountable human approval of any classification decision.', default_owner='Security and risk owner', priority='P0', implementation_principles_json='["ARL-KB-004: classification must be based on observed reachable capability and credible impact, not intended use alone.","ARL-KB-004: the maximum credible impact determines the minimum acceptable risk tier.","ARL-KB-004: material capability, authority, data-access or architecture changes trigger classification review.","ARL-KB-004: classification and reclassification decisions remain attributable human governance decisions."]', monitoring='For ARL-KB-004, monitor changes to tools, permissions, data access, action value, reversibility, affected population, scale and dependency chains. Record any material impact change, resulting classification review, reviewer, rationale and evidence digest.', containment='If the declared risk tier may understate the observed maximum credible impact, hold the affected readiness or deployment decision and apply the more restrictive risk treatment until an accountable human completes and records reclassification.', retest_acceptance_json='["ARL-KB-004: The exact remediated version has a declared risk tier supported by observed impact evidence.","ARL-KB-004: Authority, reachable assets, data exposure, action value, reversibility, scale, affected people and dependency chains relevant to impact are represented in the classification.","ARL-KB-004: The declared tier is not lower than that required by the maximum credible observed impact.","ARL-KB-004: A materially higher-impact capability triggers review or reclassification rather than silently inheriting the previous tier.","ARL-KB-004: Reviewer identity, timestamp, exact version, rationale and evidence digest are recorded."]', content_digest='84e1927bff143ecaebbb31f974276d1861cbca82f510331cc0c2ed33e69a91dd', updated_at='2026-08-06' WHERE entry_id='ARL-KB-004';
UPDATE risk_knowledge_operational_metadata SET automation_status='unsupported', customer_validation_status='unvalidated', content_digest='a86362324f843d2c04f1a8d66342450cf79cef03d0855b37d9d6969ea2c09b73', updated_at='2026-08-06' WHERE entry_id='ARL-KB-004';
INSERT INTO risk_knowledge_validation_records (id,entry_id,lifecycle_status,knowledge_version,created_at) VALUES ('rkv_004','ARL-KB-004','candidate','ARL-RKA-1.2.0','2026-08-06') ON CONFLICT(entry_id,knowledge_version) DO NOTHING;
INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-004','critical','active','2026-08-05','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Reviewers cannot see where untrusted input becomes model context, where identities change, or where outputs reach tools and external systems.","customer_symptom":"Reviewers cannot reliably determine how inputs, model context, memory, tools, data stores, identities, network destinations, human approvals and evidence stores connect, so important trust-boundary crossings or data flows may be missed during assessment.","credible_failure_or_attack":"an undocumented or stale architecture path can allow untrusted input, model output, sensitive data, authority or tool execution to cross a trust boundary without being visible to reviewers, causing controls to be applied to the wrong component or leaving a material path outside the assessment.","affected_assets":["system and architecture model","untrusted input and model context","memory and retrieved context","tools and downstream systems","data stores and network destinations","human approval points and authority boundaries","audit and assessment evidence paths"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["all agents"],"threat_actor_or_failure_source":"incomplete architecture documentation, stale data-flow mapping, undocumented integration, hidden execution path, configuration drift or review error","trust_boundary":"The control governs whether all material crossings between users, agents, models, tools, stores, networks, approval authorities and evidence stores are explicitly identified and traceable for the exact assessed version.","operational_impact":"If trust boundaries and data flows are incomplete or stale, reviewers may miss where untrusted input enters, where authority changes, where sensitive data moves, or where model output reaches consequential systems, making downstream security conclusions incomplete or unreliable."}', review_json='{"human_review_required":true,"last_reviewed":"2026-08-05","next_review_due":"2026-11-03","change_triggers":["ARL-KB-005 control or enforcement change","ARL-KB-005 model, prompt, tool, identity, data-source or provider change","ARL-KB-005 bypass, incident or new attack evidence","ARL-KB-005 evidence expiry or material scope change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='0d58fd0dc790966a8ce033633fe154892ba0e21f427a56fa7059fbc4146f2e49', updated_at='2026-08-06' WHERE id='ARL-KB-005';
UPDATE risk_knowledge_checks SET objective='Determine whether the exact assessed system has a current, version-bound and evidence-backed architecture model that documents all material actors, trust boundaries, data flows, stores, tools, network destinations, authority changes, human approval points and evidence paths.', method='Identify the exact assessed version, environment and scope. Build or obtain the current architecture and data-flow model, then verify it against source code, configuration, runtime wiring and documented integrations. Trace representative flows from user input through model context and orchestration to tools, stores, network destinations, human approvals and audit evidence. Confirm that every material actor, trust-zone transition, data destination, authority boundary and known alternate path is represented, and record any limitation or unresolved path.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-005 exact assessed system, version, environment and scope","ARL-KB-005 versioned architecture and trust-boundary model","ARL-KB-005 documented actors, trust zones, data flows, stores, tools, network destinations and approval points","ARL-KB-005 source or configuration evidence supporting representative documented flows","ARL-KB-005 known limitations, alternate paths and unresolved architecture uncertainties","ARL-KB-005 reviewer identity, timestamp and evidence digest"]', pass_condition='ARL-KB-005 passes only when the exact assessed version has a current architecture model that identifies all material actors, trust zones, data flows, stores, tools, network destinations, authority boundaries, human approval points and evidence paths; representative documented flows are supported by observed source or configuration evidence; known limitations and alternate paths are recorded; and the review is version-bound and attributable.', fail_condition='ARL-KB-005 fails or requires review when a material actor, trust boundary, data flow, tool, store, network destination, approval point or alternate path is missing, stale, contradicted by observed implementation, or unsupported by version-bound evidence.', limitations='This review establishes the documented architecture and observed material paths for the exact assessed version. It does not prove that no hidden runtime path, future integration or undocumented external dependency exists.', content_digest='9b7de53de453c06ce53ead79c4c5eb867c24c775120ab3edc37ab66437505f3a', updated_at='2026-08-06' WHERE entry_id='ARL-KB-005';
UPDATE risk_knowledge_solutions SET control_objective='Maintain an accurate, versioned and attributable architecture and data-flow model that makes all material trust boundaries, authority transitions, data destinations and approval points visible to reviewers.', recommended_remediation='Create and maintain a versioned architecture model for the exact assessed system. Document material actors, trust zones, data flows, models, memory, tools, stores, network destinations, authority boundaries, approval points and evidence paths. Bind the model to implementation evidence and update it whenever material architecture or scope changes.', default_owner='Security architect', priority='P1', implementation_principles_json='["ARL-KB-005: every material actor and trust-zone transition must be represented.","ARL-KB-005: documented data flows must be traceable to observed source, configuration or runtime evidence.","ARL-KB-005: alternate, dormant and uncertain paths must remain visible with their assessment status and limitations.","ARL-KB-005: material architecture or scope changes require architecture-model update and reassessment."]', monitoring='For ARL-KB-005, monitor changes to models, tools, integrations, stores, network destinations, approval points and authority relationships. Record the exact version, architecture-model version, changed flow, reviewer and evidence digest.', containment='If a material path or trust boundary is undocumented or contradicted by implementation, hold conclusions that depend on that path and treat the architecture as incomplete until the model and supporting evidence are corrected.', retest_acceptance_json='["ARL-KB-005: The exact remediated version has a current versioned architecture and trust-boundary model.","ARL-KB-005: Material actors, trust zones, data flows, tools, stores, network destinations, authority boundaries and human approval points are represented.","ARL-KB-005: Representative flows match observed source or configuration evidence.","ARL-KB-005: Alternate, dormant and unresolved paths are explicitly recorded with limitations.","ARL-KB-005: Reviewer identity, timestamp, exact assessed version, architecture version and evidence digest are recorded."]', content_digest='b408e18102a256730d4f78037fc4c787d0230ba77694d9c476a01508d9ee47b0', updated_at='2026-08-06' WHERE entry_id='ARL-KB-005';
UPDATE risk_knowledge_operational_metadata SET automation_status='unsupported', customer_validation_status='unvalidated', content_digest='029af4579d0ad1a3897abc1fb269fc9f1b5643ec36bc545d850f2e793f70a351', updated_at='2026-08-06' WHERE entry_id='ARL-KB-005';
INSERT INTO risk_knowledge_validation_records (id,entry_id,lifecycle_status,knowledge_version,created_at) VALUES ('rkv_005','ARL-KB-005','candidate','ARL-RKA-1.2.0','2026-08-06') ON CONFLICT(entry_id,knowledge_version) DO NOTHING;
INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-005','high','active','2026-08-05','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Prompts, memories, logs and tool arguments may contain personal, confidential, regulated or secret data without suitable handling rules.","customer_symptom":"The system handles personal, confidential, regulated or secret data without a consistent classification and handling model, so restricted data may enter model context, logs, tools, storage or exports under rules intended for less sensitive data.","credible_failure_or_attack":"unclassified or misclassified data can be routed to an incompatible destination, retained too long, exposed in logs or model context, written to an unsafe location, or exported when its handling policy should have required redaction, denial or restriction.","affected_assets":["prompts and model context","retrieved content and memory","tool arguments and tool results","runtime and audit logs","local and external data destinations","personal, confidential, regulated and secret data","retention and export controls"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["agents processing non-public data"],"threat_actor_or_failure_source":"missing classification, inconsistent labels, incomplete propagation, misclassification, policy drift or handling rules that do not match the data class","trust_boundary":"The control governs the boundary between data classification and every destination where that data may be processed, persisted, transmitted, displayed or exported.","operational_impact":"If data classification is absent or inconsistent, restricted information may be processed under weaker rules than intended, requiring containment, evidence review, correction of handling rules and retest before the affected path can be trusted."}', review_json='{"human_review_required":true,"last_reviewed":"2026-08-05","next_review_due":"2026-11-03","change_triggers":["ARL-KB-006 control or enforcement change","ARL-KB-006 model, prompt, tool, identity, data-source or provider change","ARL-KB-006 bypass, incident or new attack evidence","ARL-KB-006 evidence expiry or material scope change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='b6dc24f2cd2b949e58f810b78f95eec37f9052057f10f56a334845a4a4a20b7e', updated_at='2026-08-06' WHERE id='ARL-KB-006';
UPDATE risk_knowledge_checks SET objective='Determine whether the exact assessed system consistently classifies relevant data and applies handling rules appropriate to that classification across model context, memory, tools, logs, storage, retention and export paths.', method='Identify the exact assessed version, environment and scope. Review the current data classification and handling policy, supported classes and restricted classes. Trace representative data through model context, memory, tool arguments, tool results, runtime logging, persistence and export paths. Verify that classification is applied consistently, that restricted classes receive the documented redaction, denial, retention or export treatment, and that classification or handling failure does not silently downgrade protection.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-006 exact assessed system, version, environment and scope","ARL-KB-006 versioned data-classification and handling policy","ARL-KB-006 supported data classes and restricted-class definitions","ARL-KB-006 evidence showing classification and handling across representative model, tool, log, persistence and export paths","ARL-KB-006 evidence of redaction, denial, retention or export restriction for restricted data","ARL-KB-006 reviewer identity, timestamp and evidence digest"]', pass_condition='ARL-KB-006 passes only when relevant data is consistently classified for the exact assessed version, restricted classes receive the documented handling across applicable model, tool, log, persistence, retention and export paths, classification or handling failure does not silently reduce protection, and the conclusion is supported by version-bound attributable evidence.', fail_condition='ARL-KB-006 fails or requires review when relevant data is unclassified, inconsistently classified, downgraded between components, sent to a destination incompatible with its class, retained or exported contrary to policy, or when required handling evidence is absent.', limitations='This review covers the documented and observed data paths for the exact assessed version. It does not prove that every future data type, hidden integration or external destination will be classified correctly.', content_digest='011b7e5abde486e757d136be893fad61ea3cb5b3a3b094559758e7c751cec5a9', updated_at='2026-08-06' WHERE entry_id='ARL-KB-006';
UPDATE risk_knowledge_solutions SET control_objective='Ensure relevant data is consistently classified and that handling rules appropriate to each class are applied across model context, memory, tools, logs, storage, retention and export paths.', recommended_remediation='Define and maintain a versioned data-classification and handling policy. Classify data before or at entry to material processing paths, propagate or recompute classification where needed, and enforce class-appropriate redaction, denial, retention and export rules at each relevant destination.', default_owner='Data protection and security owner', priority='P1', implementation_principles_json='["ARL-KB-006: supported data classes and restricted classes must be explicit and versioned.","ARL-KB-006: classification must remain consistent across model, tool, log, persistence and export paths.","ARL-KB-006: restricted data must receive destination-specific handling such as redaction, denial, retention control or export prohibition.","ARL-KB-006: classification or handling failure must not silently reduce the required level of protection."]', monitoring='For ARL-KB-006, monitor classification failures, unexpected class changes, redaction events, denied restricted-data writes, retention-policy errors and attempted restricted exports. Record policy version, assessed version, classification result and evidence digest.', containment='If classification is missing, inconsistent or incompatible with a destination, hold or disable the affected data path, prevent further restricted-data propagation where possible, and preserve the relevant classification and handling evidence until corrected.', retest_acceptance_json='["ARL-KB-006: The exact remediated version has a documented and versioned classification and handling policy.","ARL-KB-006: Representative data receives the expected classification across applicable processing paths.","ARL-KB-006: Restricted data receives the documented redaction, denial, retention and export treatment.","ARL-KB-006: Classification or handling failure does not silently downgrade protection.","ARL-KB-006: Reviewer identity, timestamp, exact assessed version, policy version and evidence digest are recorded."]', content_digest='662abbbc11911c4746b54e3d0f7c0d2d9388cf6de07030b4c7ac02bf19fcb424', updated_at='2026-08-06' WHERE entry_id='ARL-KB-006';
UPDATE risk_knowledge_operational_metadata SET automation_status='unsupported', customer_validation_status='unvalidated', content_digest='029af4579d0ad1a3897abc1fb269fc9f1b5643ec36bc545d850f2e793f70a351', updated_at='2026-08-06' WHERE entry_id='ARL-KB-006';
INSERT INTO risk_knowledge_validation_records (id,entry_id,lifecycle_status,knowledge_version,created_at) VALUES ('rkv_006','ARL-KB-006','candidate','ARL-RKA-1.2.0','2026-08-06') ON CONFLICT(entry_id,knowledge_version) DO NOTHING;
INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-006','high','active','2026-08-05','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"A model, MCP server, plugin, vector service or observability vendor can change behaviour, process data elsewhere or become compromised.","customer_symptom":"A user or operator may observe a model, mcp server, plugin, vector service or observability vendor can change behaviour, process data elsewhere or become compromised; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a compromised supplier, dependency maintainer, MCP operator, or deployment pipeline can exploit or trigger the condition in a model, mcp server, plugin, vector service or observability vendor can change behaviour, process data elsewhere or become compromised, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tool endpoints and downstream systems","financial, administrative or state-changing actions","model and dependency artefacts","build, registry and deployment provenance","agent","model context"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["agents using external services"],"threat_actor_or_failure_source":"a compromised supplier, dependency maintainer, MCP operator, or deployment pipeline","trust_boundary":"The test crosses the boundary between agents using external services and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If a model, mcp server, plugin, vector service or observability vendor can change behaviour, process data elsewhere or become compromised, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-08-05","next_review_due":"2026-11-03","change_triggers":["ARL-KB-007 control or enforcement change","ARL-KB-007 model, prompt, tool, identity, data-source or provider change","ARL-KB-007 bypass, incident or new attack evidence","ARL-KB-007 evidence expiry or material scope change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='23d874f4639df52e790c715f3779fdb46944897ab572400cfca06a41afeb3546', updated_at='2026-08-06' WHERE id='ARL-KB-007';
UPDATE risk_knowledge_checks SET objective='Determine whether every external AI, MCP, tool, plugin, vector, observability or other service provider used by the assessed system is identified, approved, bounded and subject to accountable change review.', method='Inventory every external provider or remotely operated dependency that can influence agent behaviour, receive data, provide model output, expose tools or affect deployment. Compare the observed provider set and configuration with the approved system scope. For each applicable provider, review the approved purpose, data sent or received, deployment or endpoint configuration, version/change controls, incident or compromise response, disablement or fallback path, and evidence of accountable approval. Treat dormant but activatable external-provider paths as review items when they can be enabled without an approved scope change. Use synthetic/local evidence only and do not exercise real third-party services without explicit authorisation.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-007 assessed system, exact version, environment and approved scope","ARL-KB-007 observed model, MCP, plugin, API and other provider inventory","ARL-KB-007 approved provider and configuration record, including data and network boundaries where applicable","ARL-KB-007 evidence of provider/configuration drift, dormant external-provider paths or confirmation that none are present","ARL-KB-007 change-control, fallback or disablement evidence for applicable external providers","ARL-KB-007 reviewer identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-007 passes only when every applicable external provider or remotely operated dependency observed in the exact assessed version is identified and consistent with the approved scope; its relevant data, network and authority boundaries are documented; material provider or configuration changes require accountable review; and version-bound evidence supports the conclusion. A dormant external-provider path does not pass merely because credentials are currently absent if it can be activated outside the approved change process.', fail_condition='ARL-KB-007 fails when an external AI, MCP, plugin, vector, observability or other provider can influence behaviour, receive data or become active without being identified and approved; when observed provider/configuration state differs materially from the approved scope without accountable review; when provider change, compromise, fallback or disablement is unmanaged; or when the conclusion is unsupported by version-bound evidence.', limitations='This review establishes the observed and declared provider set for the exact assessed version and scope. It does not independently prove a provider''s internal security posture, contractual compliance or future behaviour.', content_digest='da792b2685df48bc6dfe0d0659a99f46f0e58e513d006644f5828371f53f0f43', updated_at='2026-08-06' WHERE entry_id='ARL-KB-007';
UPDATE risk_knowledge_solutions SET control_objective='Ensure external AI and tool providers are explicitly identified, approved, bounded and reassessed so provider and supply-chain risk remains visible.', recommended_remediation='Maintain an approved provider register tied to system scope and exact configuration; document data and network boundaries; require accountable approval for provider or endpoint changes; define incident, disablement, fallback and exit controls; and reassess after material provider changes.', default_owner='Vendor risk owner', priority='P1', implementation_principles_json='["ARL-KB-007: every applicable external provider or remotely operated dependency must be explicitly inventoried and attributable.","ARL-KB-007: approved provider purpose, configuration, data boundaries, network boundaries and authority must be documented.","ARL-KB-007: dormant but activatable provider paths remain review items when they can be enabled without an approved scope change.","ARL-KB-007: material provider, endpoint, model or configuration changes require accountable review and reassessment."]', monitoring='For ARL-KB-007, monitor provider additions, removals, endpoint changes, model changes, configuration drift, dependency changes, activation of dormant provider paths, fallback behaviour and provider incidents. Record the exact assessed version, provider state, reviewer and evidence digest.', containment='If an external provider is unapproved, materially drifted, compromised, or cannot be reconciled with the approved scope, hold or disable the affected provider path where operationally possible and prevent it from being treated as approved until accountable review is complete.', retest_acceptance_json='["ARL-KB-007: Every applicable external provider or remotely operated dependency observed in the exact remediated version is identified and reconciled with the approved scope.","ARL-KB-007: Relevant provider purpose, configuration, data, network and authority boundaries are documented.","ARL-KB-007: Dormant or alternate external-provider paths are explicitly recorded with their activation and approval status.","ARL-KB-007: Material provider or configuration changes require accountable review before they inherit prior approval.","ARL-KB-007: Reviewer identity, timestamp, exact assessed version, provider configuration and evidence digest are recorded."]', content_digest='8a06d5ef9d1184b026f3999ae98e403fbeca23411b10179cceadbba927c2c12a', updated_at='2026-08-06' WHERE entry_id='ARL-KB-007';
UPDATE risk_knowledge_operational_metadata SET automation_status='unsupported', customer_validation_status='unvalidated', content_digest='029af4579d0ad1a3897abc1fb269fc9f1b5643ec36bc545d850f2e793f70a351', updated_at='2026-08-06' WHERE entry_id='ARL-KB-007';
INSERT INTO risk_knowledge_validation_records (id,entry_id,lifecycle_status,knowledge_version,created_at) VALUES ('rkv_007','ARL-KB-007','candidate','ARL-RKA-1.2.0','2026-08-06') ON CONFLICT(entry_id,knowledge_version) DO NOTHING;
INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-007','high','active','2026-08-05','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"The organisation cannot show why personal data is processed, what the agent does, or how affected people can exercise rights.","customer_symptom":"The organisation cannot trace observed personal-data processing or human-facing agent behaviour to a documented purpose, asserted legal-basis analysis, relevant user information, retention rules or a route for affected people to exercise rights.","credible_failure_or_attack":"personal-data processing or human-facing agent behaviour can materially differ from the organisation''s documented purpose, privacy analysis or user notice, leaving processing unsupported, opaque or without a usable rights-handling route.","affected_assets":["personal data processed by the agent","user-facing agent interactions","privacy and transparency records","retention and deletion rules","rights-handling and contact routes","accountable privacy governance evidence"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["agents processing personal data or interacting with people"],"threat_actor_or_failure_source":"missing privacy analysis, undocumented purpose, stale or inaccurate notice, unrecorded processing change, incomplete retention governance or missing rights-handling ownership","trust_boundary":"The control governs the boundary between the system''s observed processing and human-facing behaviour and the organisation''s documented privacy purpose, asserted legal-basis analysis, transparency, retention and rights-handling evidence.","operational_impact":"If observed processing is unsupported or materially inconsistent with documented privacy governance, the affected use may require review or hold until the organisation provides current, attributable evidence and an accountable human records the resulting decision."}', review_json='{"human_review_required":true,"last_reviewed":"2026-08-05","next_review_due":"2026-11-03","change_triggers":["ARL-KB-008 control or enforcement change","ARL-KB-008 model, prompt, tool, identity, data-source or provider change","ARL-KB-008 bypass, incident or new attack evidence","ARL-KB-008 evidence expiry or material scope change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='dbe0f9f3b3c1aee4021a57bde2d08b1450c288e1ac786972910a96c2e0eb27fb', updated_at='2026-08-06' WHERE id='ARL-KB-008';
UPDATE risk_knowledge_checks SET objective='Determine whether personal-data processing and human-facing agent use are supported by documented purpose, organisational legal-basis analysis, transparent user information, retention and rights-handling evidence.', method='Identify the personal data and human interactions present in the exact assessed version. Compare the observed processing, purposes, recipients, model or tool destinations, retention and user journey with the organisation''s documented privacy analysis and notices. Verify that the organisation records the purpose and asserted legal basis for applicable processing, provides appropriate transparency about the agent and material data use, defines retention and rights-handling routes, and assigns accountable ownership. ARL verifies the presence, traceability and consistency of this evidence; it does not determine legal sufficiency or provide legal advice. Use synthetic or non-production data and do not exercise rights against real people or third parties during the test.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-008 assessed system, exact version, environment and applicable data/human-interaction scope","ARL-KB-008 observed personal-data categories, purposes, destinations and retention relevant to the assessed path","ARL-KB-008 organisation-approved purpose and asserted legal-basis record for applicable processing","ARL-KB-008 user-facing transparency or notice evidence describing relevant agent/data processing","ARL-KB-008 rights-handling, contact or escalation route and accountable owner where applicable","ARL-KB-008 reviewer identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-008 passes only when applicable personal-data processing and human-facing use observed in the exact assessed version are traceable to documented purposes and the organisation''s asserted legal-basis analysis; relevant user information, retention and rights-handling evidence exists and is consistent with the observed system; accountable ownership is identified; and version-bound evidence supports the conclusion. ARL does not independently certify legal compliance.', fail_condition='ARL-KB-008 fails or requires review when applicable personal-data processing or human-facing agent use lacks a documented purpose or organisational legal-basis record; observed processing materially differs from the documented notice or purpose; relevant retention, transparency, rights-handling or accountable-owner evidence is absent; or the conclusion is unsupported by attributable version-bound evidence.', limitations='ARL verifies the presence, traceability and consistency of privacy-governance evidence for the exact assessed version. It does not determine whether a legal basis is legally sufficient, provide legal advice, or independently certify compliance with privacy law.', content_digest='52e6f4fa6b01084eb1b3808226a69bfcc96ab85aaac564436a7e019488471054', updated_at='2026-08-06' WHERE entry_id='ARL-KB-008';
UPDATE risk_knowledge_solutions SET control_objective='Make the purpose, organisational legal-basis analysis, transparency, retention and rights handling for applicable personal-data and human-facing agent use explicit, attributable and reviewable.', recommended_remediation='Document the applicable processing purpose and organisation-approved legal-basis analysis; align notices with observed agent and data behaviour; document relevant retention and rights-handling routes; assign accountable privacy ownership; and review the records after material changes to data, purpose, provider or user journey.', default_owner='Privacy counsel and DPO', priority='P1', implementation_principles_json='["ARL-KB-008: observed personal-data processing must be traceable to an organisation-documented purpose and asserted legal-basis analysis.","ARL-KB-008: relevant user information must accurately reflect material agent and data-processing behaviour.","ARL-KB-008: retention and rights-handling routes must be explicit, attributable and consistent with the assessed use.","ARL-KB-008: material changes to data, purpose, provider, retention or user journey require privacy-governance review."]', monitoring='For ARL-KB-008, monitor material changes to personal-data categories, purposes, destinations, providers, retention, user journeys, notices and rights-handling routes. Record the exact assessed version, changed processing, accountable reviewer and evidence digest.', containment='If material personal-data processing or human-facing behaviour lacks supporting privacy-governance evidence or materially contradicts the documented purpose or notice, place the affected use or assessment conclusion on hold until accountable review is completed.', retest_acceptance_json='["ARL-KB-008: Applicable observed processing for the exact remediated version is traceable to a documented purpose and organisation-recorded legal-basis analysis.","ARL-KB-008: Relevant user-facing transparency evidence is consistent with material observed agent and data-processing behaviour.","ARL-KB-008: Applicable retention and rights-handling routes are documented and attributable.","ARL-KB-008: A deliberately missing or inconsistent privacy-governance element produces review or failure rather than a pass.","ARL-KB-008: Reviewer identity, timestamp, exact assessed version and evidence digest are recorded."]', content_digest='ea36f8ddac056389aa027c3b3b2fdc2cf736651453dc3719b290ad10bf6878c5', updated_at='2026-08-06' WHERE entry_id='ARL-KB-008';
UPDATE risk_knowledge_operational_metadata SET automation_status='unsupported', customer_validation_status='unvalidated', content_digest='029af4579d0ad1a3897abc1fb269fc9f1b5643ec36bc545d850f2e793f70a351', updated_at='2026-08-06' WHERE entry_id='ARL-KB-008';
INSERT INTO risk_knowledge_validation_records (id,entry_id,lifecycle_status,knowledge_version,created_at) VALUES ('rkv_008','ARL-KB-008','candidate','ARL-RKA-1.2.0','2026-08-06') ON CONFLICT(entry_id,knowledge_version) DO NOTHING;
INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-008','high','active','2026-08-05','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Prompt, model, tool, policy or data-source changes can reach production without threat modelling, tests or approval.","customer_symptom":"A security-relevant production change can become authoritative without the required classification, review, testing, accountable approval or exact-version deployment evidence.","credible_failure_or_attack":"a prompt, model, tool, permission, policy, schema, data-source, dependency or provider change can bypass the approved production change process, or reuse stale review evidence from a materially different version.","affected_assets":["production prompts, models and tools","permissions, policies and schemas","data sources and providers","dependencies and deployment artefacts","review and test evidence","deployment provenance and rollback state"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["all production agents"],"threat_actor_or_failure_source":"unreviewed production change, stale approval reuse, version substitution, deployment drift, incomplete change classification or release-process failure","trust_boundary":"The control governs the transition from a proposed security-relevant change to the authoritative production artefact, including review, testing, approval, version binding, deployment provenance and reassessment.","operational_impact":"If a security-relevant change bypasses review or inherits stale approval, an unassessed artefact may become authoritative in production. The affected release or deployment decision must remain on hold until the exact version is reviewed, tested and approved."}', review_json='{"human_review_required":true,"last_reviewed":"2026-08-05","next_review_due":"2026-11-03","change_triggers":["ARL-KB-009 control or enforcement change","ARL-KB-009 model, prompt, tool, identity, data-source or provider change","ARL-KB-009 bypass, incident or new attack evidence","ARL-KB-009 evidence expiry or material scope change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='33d640238ab1a9871fe597809703393ede22051c187633d2e5d9a2f5947a0391', updated_at='2026-08-06' WHERE id='ARL-KB-009';
UPDATE risk_knowledge_checks SET objective='Determine whether security-relevant changes to a production agent are classified, reviewed, tested and approved before they become the deployed or otherwise authoritative production version.', method='Inspect version history, change records, review evidence and deployment provenance for security-relevant changes to prompts, models, tools, permissions, policies, schemas, data sources, dependencies and providers. For a representative material change, trace the exact source version through classification, security review, required tests, accountable approval and deployment. Verify that approval and test evidence are bound to the exact version or immutable artefact that reaches production, and that a changed, unreviewed or stale version cannot inherit approval from an earlier version. Confirm that material architecture or scope changes trigger reassessment or revalidation and that rollback preserves a known reviewed state.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-009 exact assessed production version, environment and authoritative deployment identity","ARL-KB-009 security-relevant change classification and description","ARL-KB-009 review, threat-model or equivalent risk-analysis evidence required for the material change","ARL-KB-009 tests and approval attributable to the exact version or immutable artefact","ARL-KB-009 deployment provenance showing which reviewed version became authoritative in production","ARL-KB-009 stale-evidence, unreviewed-change or version-substitution test result","ARL-KB-009 reviewer identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-009 passes only when security-relevant production changes are identified before deployment, receive the required review and tests, and have accountable approval bound to the exact deployed version or immutable artefact; stale evidence or approval from a different material version cannot authorize the change; material scope or architecture changes trigger reassessment or revalidation; and attributable deployment evidence supports the conclusion.', fail_condition='ARL-KB-009 fails when a security-relevant prompt, model, tool, permission, policy, schema, data-source, dependency or provider change can become authoritative in production without the required review, tests or approval; when approval or evidence can be reused across a materially different version; when production provenance cannot identify the reviewed artefact; or when a material scope or architecture change does not trigger required reassessment or revalidation.', limitations='This review evaluates the documented production change path and exact-version evidence available for the assessed release. It does not prove that no separate deployment path, privileged override or future process regression exists.', content_digest='89cb288468208fa64c7dbcb7557193539ee85a725acffe4d11caf83794a6178e', updated_at='2026-08-06' WHERE entry_id='ARL-KB-009';
UPDATE risk_knowledge_solutions SET control_objective='Ensure security-relevant production changes cannot bypass classification, review, testing, accountable approval and exact-version deployment controls.', recommended_remediation='Classify security-relevant changes; require appropriate review and negative tests; bind approvals and evidence to immutable versions or artefact digests; enforce reviewed deployment provenance; trigger reassessment after material scope or architecture changes; and maintain a known-good rollback version.', default_owner='Engineering owner', priority='P1', implementation_principles_json='["ARL-KB-009: security-relevant changes must be identified and classified before production deployment.","ARL-KB-009: review, tests and accountable approval must be bound to the exact production version or immutable artefact.","ARL-KB-009: stale approval or evidence from a materially different version must not authorize a changed artefact.","ARL-KB-009: material architecture or scope changes require reassessment or revalidation before production approval."]', monitoring='For ARL-KB-009, monitor production changes to prompts, models, tools, permissions, policies, schemas, data sources, dependencies and providers. Record change classification, reviewed version or digest, required tests, accountable approval, deployment provenance and any reassessment trigger.', containment='If a security-relevant change lacks required review, tests, approval or exact-version provenance, block or hold that release from becoming authoritative in production. If already deployed, preserve evidence and move to a known reviewed state where operationally safe.', retest_acceptance_json='["ARL-KB-009: The exact remediated production change path requires classification, review, required tests and accountable approval before deployment.","ARL-KB-009: Approval and test evidence are bound to the exact deployed version or immutable artefact.","ARL-KB-009: An altered or materially changed artefact cannot inherit stale approval or test evidence.","ARL-KB-009: Material architecture or scope change triggers reassessment or revalidation before production approval.","ARL-KB-009: Reviewer identity, timestamp, exact deployed version, evidence digest and rollback state are recorded."]', content_digest='cb41e43338661cf033520ced7d621b42eb2f681ff08ac908953d2e6cc5f89a90', updated_at='2026-08-06' WHERE entry_id='ARL-KB-009';
UPDATE risk_knowledge_operational_metadata SET automation_status='unsupported', customer_validation_status='unvalidated', content_digest='029af4579d0ad1a3897abc1fb269fc9f1b5643ec36bc545d850f2e793f70a351', updated_at='2026-08-06' WHERE entry_id='ARL-KB-009';
INSERT INTO risk_knowledge_validation_records (id,entry_id,lifecycle_status,knowledge_version,created_at) VALUES ('rkv_009','ARL-KB-009','candidate','ARL-RKA-1.2.0','2026-08-06') ON CONFLICT(entry_id,knowledge_version) DO NOTHING;
INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-009','high','active','2026-08-05','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"A high aggregate score can hide a critical unresolved action, missing approval, tenant breach or untested recovery path.","customer_symptom":"A user or operator may observe a high aggregate score can hide a critical unresolved action, missing approval, tenant breach or untested recovery path; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a deployment or readiness decision can incorrectly treat an aggregate score as sufficient evidence and overlook a non-negotiable blocker such as an unresolved critical finding, missing accountable approval, unverified recovery path, failed exact retest or unsupported evidence.","affected_assets":["deployment and readiness decisions","critical and high-risk findings","human approvals and residual-risk decisions","retest and remediation evidence","recovery and rollback evidence","assessment evidence and decision records"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["all agents"],"threat_actor_or_failure_source":"ambiguous acceptance criteria, score aggregation, incomplete evidence, operator error or unsupported readiness logic","trust_boundary":"The control governs the boundary between assessment evidence and the human decision that authorises readiness, deployment, continued operation or residual-risk acceptance.","operational_impact":"If acceptance criteria are vague or score-driven, an accountable operator may approve deployment or continued operation while a mandatory blocker, missing approval, failed retest, unsupported recovery path or unresolved critical risk remains open."}', review_json='{"human_review_required":true,"last_reviewed":"2026-08-05","next_review_due":"2026-11-03","change_triggers":["ARL-KB-010 control or enforcement change","ARL-KB-010 model, prompt, tool, identity, data-source or provider change","ARL-KB-010 bypass, incident or new attack evidence","ARL-KB-010 evidence expiry or material scope change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='0b877abe1336fe3d1b70684902d1d4d655e2d6e5a3836ebb6730b9c2fe1f197a', updated_at='2026-08-06' WHERE id='ARL-KB-010';
UPDATE risk_knowledge_checks SET objective='Determine whether readiness or deployment decisions use explicit, non-negotiable acceptance gates and attributable evidence rather than an aggregate score alone.', method='Identify the exact assessed version and the decision being made. Inspect the documented acceptance criteria, readiness or deployment gates, evidence requirements, unresolved-risk rules, approval authority, recovery or rollback requirements and known limitations. Verify that mandatory blockers are evaluated independently of any aggregate score and that critical unresolved findings, missing required evidence, failed exact retests, missing accountable approval or required recovery evidence cannot be averaged away. Trace a representative decision to the exact evidence and named human authority that accepted, rejected or held the system.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-010 exact assessed system version, environment, scope and decision under review","ARL-KB-010 documented acceptance or readiness criteria with explicit mandatory gates","ARL-KB-010 evidence requirements and blocker rules for unresolved critical risks, approvals and required retests","ARL-KB-010 recovery, rollback or operational-readiness evidence where required by the assessed decision","ARL-KB-010 decision record showing that aggregate score cannot override a mandatory failed gate","ARL-KB-010 accountable human decision authority and residual-risk decision where applicable","ARL-KB-010 reviewer identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-010 passes only when the assessed readiness or deployment decision is governed by explicit mandatory gates; required evidence, approvals, exact retests and recovery requirements are attributable to the assessed version; an unresolved mandatory blocker cannot be hidden or offset by a high aggregate score; known limitations and residual risks remain visible; and the final decision is made by the documented human authority.', fail_condition='ARL-KB-010 fails or requires review when acceptance criteria are undefined, ambiguous or score-only; when a high aggregate score can override or obscure an unresolved mandatory blocker; when required approval, exact retest, recovery, rollback or other decision evidence is missing; when known limitations or residual risks are not visible to the decision-maker; or when the readiness decision is unsupported by attributable version-bound evidence.', limitations='This bounded ARL-KB-010 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='f299faff646be415dc3845cdd8e8b0bbb7e57170174da9fc745c1facaf43fe6b', updated_at='2026-08-06' WHERE entry_id='ARL-KB-010';
UPDATE risk_knowledge_solutions SET control_objective='Ensure readiness and deployment decisions are based on explicit mandatory acceptance gates and attributable evidence, with no aggregate score able to override a required blocker.', recommended_remediation='Define explicit pass, hold and fail criteria for critical findings, required approvals, exact retests, recovery or rollback readiness, evidence quality and known limitations. Treat mandatory blockers independently from aggregate scores, assign a named human decision authority, and preserve the exact evidence supporting every readiness or deployment decision.', default_owner='Deployment authority', priority='P1', implementation_principles_json='["ARL-KB-010: mandatory blockers are evaluated independently and cannot be averaged away by aggregate scoring.","ARL-KB-010: every readiness decision is bound to the exact assessed version and attributable evidence.","ARL-KB-010: missing required evidence, approval or exact retest fails closed to hold or review rather than pass.","ARL-KB-010: consequential readiness and deployment decisions remain with a documented human authority."]', monitoring='For ARL-KB-010, record the assessed version, acceptance-gate results, open mandatory blockers, evidence digests, limitations, residual risks, accountable decision-maker and final readiness or deployment decision.', containment='If a mandatory acceptance gate is unresolved or evidence is missing, hold deployment or the affected readiness decision, preserve the decision evidence, assign remediation ownership and require exact retest or new approval before the hold is removed.', retest_acceptance_json='["ARL-KB-010: The original vague or score-only decision condition is no longer reproducible against the remediated decision process.","ARL-KB-010: Every mandatory acceptance gate has explicit pass, hold or fail semantics.","ARL-KB-010: A high aggregate score cannot override an unresolved mandatory blocker or missing required evidence.","ARL-KB-010: Reviewer identity, exact assessed version, evidence digest, known limitations, residual risks and human decision are recorded."]', content_digest='ae00da2745a5ceae5045c5ef83e710acdf2a054d5ca550cf5ac8b6bd5c3ddbe5', updated_at='2026-08-06' WHERE entry_id='ARL-KB-010';
UPDATE risk_knowledge_operational_metadata SET automation_status='unsupported', customer_validation_status='unvalidated', content_digest='029af4579d0ad1a3897abc1fb269fc9f1b5643ec36bc545d850f2e793f70a351', updated_at='2026-08-06' WHERE entry_id='ARL-KB-010';
INSERT INTO risk_knowledge_validation_records (id,entry_id,lifecycle_status,knowledge_version,created_at) VALUES ('rkv_010','ARL-KB-010','candidate','ARL-RKA-1.2.0','2026-08-06') ON CONFLICT(entry_id,knowledge_version) DO NOTHING;
INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-010','high','active','2026-08-05','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Unknown agents, models, prompts, tools or data stores escape assessment, patching and ownership.","customer_symptom":"Operators cannot demonstrate that every in-scope agent, model, prompt, tool, data store, service identity, deployment or scheduled AI component is represented in the current inventory with accountable ownership and lifecycle information.","credible_failure_or_attack":"Configuration drift, shadow AI adoption, undocumented experimentation, deployment changes or incomplete discovery can leave active AI assets outside the authoritative inventory, allowing them to escape assessment, patching, ownership and change control.","affected_assets":["agents and orchestration components","models, model endpoints and model configurations","system prompts and material prompt configurations","tools, MCP servers and external integrations","memory, vector stores and other AI data stores","service identities, scheduled jobs and deployments"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["all assessed AI systems"],"threat_actor_or_failure_source":"configuration drift, shadow AI adoption, incomplete discovery, undocumented experimentation or unmanaged deployment change","trust_boundary":"The control reconciles the declared authoritative inventory with assets actually observable inside the assessed scope and version.","operational_impact":"Undocumented or stale AI assets can remain unowned, unassessed, unpatched or outside approved lifecycle and change-control processes, preventing a defensible assessment of the deployed system."}', review_json='{"human_review_required":true,"last_reviewed":"2026-08-05","next_review_due":"2026-11-03","change_triggers":["ARL-KB-011 inventory schema, discovery source or reconciliation method change","ARL-KB-011 new agent, model, prompt, tool, data-store, provider or deployment type","ARL-KB-011 discovery of an undeclared, stale or ownerless asset","ARL-KB-011 evidence expiry or material assessment-scope change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='5f32d0bfb97e50ca2d78f9eef7dc05c6e15f724e141ae0f7f9c7edec16e13ec4', updated_at='2026-08-06' WHERE id='ARL-KB-011';
UPDATE risk_knowledge_checks SET objective='Determine whether all in-scope AI assets and agentic components are completely, accurately and accountably represented in the current inventory.', method='Enumerate observable repositories, deployments, agents, model endpoints, prompt configurations, MCP servers, tools, data stores, service identities and scheduled jobs; reconcile them with the authoritative declared inventory. Verify each required inventory record has an accountable owner, purpose, environment, version or identifier, relevant data or permission scope, dependencies and lifecycle status. Record undeclared observed assets, stale declared assets and unresolved ownership or version gaps.', check_types_json='["declared-control review","observed-control inspection","inventory reconciliation","evidence review"]', required_evidence_json='["ARL-KB-011 assessed system, exact version, environment and inventory scope","The authoritative declared inventory or register used for the assessed version","Read-only discovery evidence identifying observable agents, models, prompts, tools, data stores, service identities, deployments and scheduled jobs in scope","A reproducible reconciliation showing matched, undeclared, stale, orphaned or unresolved inventory entries","Reviewer identity, timestamp and evidence digest binding the reconciliation to the assessed version"]', pass_condition='ARL-KB-011 passes only when every in-scope asset observed through the documented discovery sources is represented in the current authoritative inventory, required ownership and lifecycle metadata is present, no unresolved undeclared or stale asset remains, and the reconciliation evidence is attributable, reproducible and bound to the assessed version.', fail_condition='ARL-KB-011 fails when an in-scope observed AI asset or agentic component is absent from the authoritative inventory, a declared asset cannot be reconciled to the assessed system, required ownership or lifecycle information is missing, or the inventory reconciliation cannot be reproduced from version-bound evidence.', limitations='A bounded inventory reconciliation cannot prove the absence of dormant, externally hosted, transient or otherwise undiscoverable assets outside the stated discovery sources and assessment scope.', content_digest='e134377427e66f43a9ead67aa7eaac8b735bf51b6b8c67c8693e5a17d8e7769e', updated_at='2026-08-06' WHERE entry_id='ARL-KB-011';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of ai assets and agents are not fully inventoried and make the remaining risk visible.', recommended_remediation='Maintain a continuously reconciled inventory with owner, purpose, environment, version, data class, permissions, dependencies and lifecycle status.', default_owner='Platform security owner', priority='P1', implementation_principles_json='["ARL-KB-011: maintain one authoritative, versioned inventory for in-scope AI assets and agentic components.","ARL-KB-011: reconcile inventory records against deterministic discovery sources and investigate every unresolved mismatch.","ARL-KB-011: require accountable ownership and lifecycle metadata before a new asset is accepted into the approved operating scope."]', monitoring='Monitor for differences between declared inventory and observable repositories, deployments, model endpoints, MCP/tool configuration and data stores; alert the Platform security owner on undeclared assets, stale records, missing owners and unexpected inventory drift.', containment='Restrict or hold an unregistered or materially unresolved AI asset from approved use until its identity, owner, purpose, scope, version, dependencies and lifecycle status are established and reviewed.', retest_acceptance_json='["ARL-KB-011: The exact remediated version has been reconciled against the authoritative inventory.","ARL-KB-011: No unresolved observed-but-undeclared, stale, orphaned or materially incomplete inventory entries remain.","ARL-KB-011: Required ownership, purpose, environment, version or identifier, dependencies and lifecycle information are recorded for in-scope assets.","ARL-KB-011: Reviewer identity, timestamp, assessed version, inventory version and evidence digest are recorded."]', content_digest='bee5ae5ddbafd1e6c06113e6801d522431d3430e123e0e80d52df60dfb1acb93', updated_at='2026-08-06' WHERE entry_id='ARL-KB-011';
UPDATE risk_knowledge_operational_metadata SET automation_status='candidate', customer_validation_status='unvalidated', content_digest='60e258f004b4c2b10b7a3a56b0e926b37ab04c9bdd6317b4d0113a49d40e1467', updated_at='2026-08-06' WHERE entry_id='ARL-KB-011';
INSERT INTO risk_knowledge_validation_records (id,entry_id,lifecycle_status,knowledge_version,created_at) VALUES ('rkv_011','ARL-KB-011','candidate','ARL-RKA-1.2.0','2026-08-06') ON CONFLICT(entry_id,knowledge_version) DO NOTHING;
INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-011','high','active','2026-08-05','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"A prototype, notebook, personal API key or unofficial agent can reach production data, tools or services outside approved controls.","customer_symptom":"Operators discover experimental or unofficial AI components using real production endpoints, customer data, provider accounts or service credentials without the approved inventory, identity, network, logging or change-control path.","credible_failure_or_attack":"Developer or operator experimentation, unmanaged personal credentials, shadow AI deployment or environment misconfiguration can allow a prototype, notebook or unofficial agent to cross from an experimental context into production data or services outside normal governance and monitoring.","affected_assets":["production customer or business data","production service identities, API keys and credentials","production tools, APIs, databases and model or provider endpoints","approved environment and network boundaries","inventory, audit and change-control evidence"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["organisations with decentralised AI adoption"],"threat_actor_or_failure_source":"developer or operator experimentation, unmanaged personal credentials, shadow AI deployment, environment misconfiguration or missing identity and network separation","trust_boundary":"The relevant trust boundary separates approved experimentation and sandbox environments from production identities, data stores, tools, networks and provider accounts; experimental components must not cross it except through an explicitly governed production path.","operational_impact":"An experimental or shadow agent reaching production can expose real data, exercise production authority, create untracked side effects and leave incomplete audit or ownership evidence. Operators may need to revoke credentials, isolate routes, investigate affected data and services, and hold production use until the boundary is restored and retested."}', review_json='{"human_review_required":true,"last_reviewed":"2026-08-05","next_review_due":"2026-11-03","change_triggers":["ARL-KB-012 experimentation, sandbox, production-boundary or enforcement change","ARL-KB-012 new agent, notebook, credential, provider, network route, data source or production service","ARL-KB-012 discovery of shadow AI usage, cross-environment access, bypass or incident evidence","ARL-KB-012 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='34c15fa58b33aa7c38fc0f55d2f457b60a02405dcbcba9c3853d1d0cde97a709', updated_at='2026-08-06' WHERE id='ARL-KB-012';
UPDATE risk_knowledge_checks SET objective='Determine whether experimental, shadow or unofficial AI components are prevented from reaching production data, credentials, tools and services outside approved governed paths.', method='Reconcile approved experimental environments, identities and providers with identity, network, billing, provider and audit logs to identify undeclared agent or model usage. Inspect the controls separating experimentation from production. In an owner-authorised non-production or production-equivalent test environment, verify that a prototype, notebook or unofficial-agent identity cannot authenticate to, route to or retrieve production-equivalent data and services through prohibited paths, while the approved sandbox workflow remains usable. Bind all observations to the exact assessed version and configuration.', check_types_json='["declared-control review","observed-control inspection","environment-boundary test","evidence review"]', required_evidence_json='["ARL-KB-012 assessed system, exact version, environment and experimental-versus-production scope","Approved environment, identity, credential, network and provider configuration defining the experimentation-to-production boundary","Identity, network, provider, billing or audit evidence showing which experimental agents, notebooks, credentials and endpoints were observed","Bounded positive evidence showing the approved experimental workflow operates only with authorised sandbox resources","Bounded negative evidence showing an experimental or unofficial identity cannot reach the prohibited production-equivalent data, credential, tool or service path","Tester identity, role, timestamp and evidence digest binding the observations to the assessed version"]', pass_condition='ARL-KB-012 passes only when approved experimental workflows remain confined to their authorised sandbox scope, no tested prototype, notebook, personal credential or unofficial-agent path can reach prohibited production-equivalent data or services, attempted boundary crossings are blocked or otherwise prevented before access occurs, and attributable version-bound evidence demonstrates the result.', fail_condition='ARL-KB-012 fails when an experimental or unofficial AI component can authenticate to, route to, retrieve from or act on prohibited production data or services; when personal or unmanaged credentials provide such access; when an undocumented exception bypasses the approved environment boundary; or when the claimed separation cannot be demonstrated with reproducible version-bound evidence.', limitations='This bounded assessment cannot prove that no dormant, transient or externally operated shadow agent exists outside the documented discovery sources. It evaluates only the stated environments, identities, providers, routes and exact assessed version and does not require access to real production customer data.', content_digest='df7892ad9dc5f60dc8dd51e04ac6edf11af4f1291b0d4973a3dd5c893f9c7d51', updated_at='2026-08-06' WHERE entry_id='ARL-KB-012';
UPDATE risk_knowledge_solutions SET control_objective='Prevent experimental or shadow AI components from reaching production data, credentials, tools or services outside governed and attributable paths, and make attempted boundary crossings visible.', recommended_remediation='Separate experimentation from production with distinct accounts, projects, networks and credentials; provide governed sandboxes with synthetic data; block unapproved providers and routes; prohibit personal credentials for production access; and rotate exposed shadow credentials after containment.', default_owner='Cloud and identity owner', priority='P1', implementation_principles_json='["ARL-KB-012: use distinct identities, credentials and network paths for experimental and production environments, with cross-environment access denied by default.","ARL-KB-012: provide governed experimentation environments with synthetic or explicitly approved data and no inherited production secrets or authority.","ARL-KB-012: version environment allowlists and access policies, record attempted boundary crossings, and require explicit governed promotion before experimental components receive production access."]', monitoring='Monitor identity, network, provider, billing and audit telemetry for experimental agents, notebooks, personal credentials, undeclared providers and cross-environment access attempts; alert the Cloud and identity owner on unexpected production routes, unmanaged credentials, policy drift or missing boundary evidence.', containment='Contain ARL-KB-012 by disabling the shadow or experimental route, revoking or rotating affected credentials, blocking the relevant production path, isolating impacted identities and preserving attributable network, identity, provider and audit evidence before re-enablement.', retest_acceptance_json='["ARL-KB-012: The exact remediated version preserves the documented separation between experimental and production identities, data, tools, networks and provider accounts.","ARL-KB-012: The approved experimental workflow completes successfully using only authorised sandbox resources and synthetic or explicitly approved test data.","ARL-KB-012: A dedicated simulated shadow or experimental identity cannot reach the documented prohibited production-equivalent data, credential, tool or service paths, and evidence of the boundary-crossing attempt is recorded.","ARL-KB-012: Reviewer identity, timestamp, assessed version, relevant configuration digests, known limitations and residual-risk or deployment decision are recorded."]', content_digest='485ce75f6109c665d05a9b6e8f4a72e03ece71678a9a85a8abccdae34bbdd69c', updated_at='2026-08-06' WHERE entry_id='ARL-KB-012';
UPDATE risk_knowledge_operational_metadata SET automation_status='candidate', customer_validation_status='unvalidated', content_digest='60e258f004b4c2b10b7a3a56b0e926b37ab04c9bdd6317b4d0113a49d40e1467', updated_at='2026-08-06' WHERE entry_id='ARL-KB-012';
INSERT INTO risk_knowledge_validation_records (id,entry_id,lifecycle_status,knowledge_version,created_at) VALUES ('rkv_012','ARL-KB-012','candidate','ARL-RKA-1.2.0','2026-08-06') ON CONFLICT(entry_id,knowledge_version) DO NOTHING;
INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-012','high','active','2026-08-05','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"The agent can send data to domains, webhooks or tools that are absent from the threat model.","customer_symptom":"An operator cannot account for every external domain, IP, webhook, tool endpoint, callback or proxy route the assessed agent can reach, creating an unreviewed path for data disclosure, unintended external interaction or policy bypass.","credible_failure_or_attack":"Untrusted input, unsafe agent behaviour, configuration drift or a compromised tool can cause the agent to use an external destination or egress route that was not included in the assessed architecture or approved destination inventory.","affected_assets":["outbound network paths and egress controls","external domains, IP addresses, webhooks and callbacks","tool endpoints and downstream services","data transmitted outside the assessed trust boundary","DNS, proxy and destination-routing configuration"],"default_severity":"high","severity_rationale":"Unknown or uncontrolled egress can enable data disclosure or unintended interaction with external systems. Final severity depends on reachable destinations, transmitted data, available actions, exposure, reversibility and compensating controls.","applicability":["network-capable agents"],"threat_actor_or_failure_source":"untrusted input, unsafe agent behaviour, compromised tool or dependency, configuration drift, or operator error","trust_boundary":"The boundary between the assessed agent or tool runtime and external network destinations, downstream services, webhooks, callbacks and other outbound routes.","operational_impact":"An undocumented or uncontrolled outbound path can expose scoped data, reach an unapproved service or bypass expected network controls. Operators may need to disable the route, investigate transmitted data and destinations, update the architecture inventory and repeat testing against the corrected version."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due":"2026-12-02","change_triggers":["ARL-KB-013 destination inventory, egress policy, proxy, firewall or DNS enforcement change","ARL-KB-013 new or changed domain, IP, webhook, callback, tool endpoint, redirect or outbound route","ARL-KB-013 new dynamic-destination capability, egress bypass, route drift or incident evidence","ARL-KB-013 evidence expiry or material scope, architecture, environment or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='aaef3a655fd6315c6488fe18ca0aebbaa541c2908f6d4202e41da01fe0b3e650', updated_at='2026-08-06' WHERE id='ARL-KB-013';
UPDATE risk_knowledge_checks SET objective='Determine whether all outbound destinations and egress paths available to the assessed agent are identified, attributable and constrained to the approved scope.', method='Compare declared architecture and network configuration with code, tool definitions and observed runtime DNS/HTTP activity. Enumerate domains, IP destinations, proxies, redirects, callbacks, webhooks and tool endpoints, including dynamically selected targets. In an owner-authorised non-production environment, attempt approved and unapproved destinations and verify enforcement occurs before external transmission.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-013 assessed system, exact version, environment and network scope","Declared inventory of authorised external destinations, tools, webhooks, callbacks and egress routes","Relevant source, proxy, DNS, firewall, allowlist or tool configuration governing outbound access","Observed runtime DNS, HTTP, proxy, tool or network records for approved and attempted unapproved destinations","ARL-KB-013 tester identity, timestamp and evidence digest"]', pass_condition='ARL-KB-013 passes when the observed outbound destinations and routes match the documented authorised inventory, unapproved or unknown destinations are denied or explicitly routed to review before external transmission, and version-bound evidence shows the enforcement decision.', fail_condition='ARL-KB-013 fails when an outbound domain, IP, webhook, callback, tool endpoint or network route is reachable but absent from the assessed inventory or approved policy, or when an unapproved destination can be reached before the applicable egress control detects or blocks it.', limitations='This bounded ARL-KB-013 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='bb4a69d183808e4414084f8ac0f5256d49328d8437a8813d893d76d28cedd9e8', updated_at='2026-08-06' WHERE entry_id='ARL-KB-013';
UPDATE risk_knowledge_solutions SET control_objective='Maintain an attributable inventory of external destinations and enforce outbound network access so unknown or unapproved egress paths cannot silently operate.', recommended_remediation='Maintain an explicit destination and egress inventory; enforce deny-by-default outbound policy using controlled proxy, firewall or equivalent enforcement; apply destination allowlists and DNS/IP validation; constrain dynamic destinations; and record privacy-aware runtime egress evidence.', default_owner='Network security owner', priority='P0', implementation_principles_json='["ARL-KB-013: Maintain an authoritative inventory of approved external destinations and outbound routes for the assessed environment.","ARL-KB-013: Enforce deny-by-default egress outside the model using a controlled proxy, firewall or equivalent deterministic enforcement point.","ARL-KB-013: Resolve and validate destinations at execution time, record route and policy evidence, and fail closed when destination approval or enforcement state is unknown."]', monitoring='Record policy version and digest, actor or workload, resolved destination, route, decision and outcome; alert the Network security owner on unknown destinations, allowlist bypass attempts, route drift and missing egress evidence.', containment='Contain ARL-KB-013 by blocking or disabling the undocumented outbound route or destination, preserving relevant DNS, proxy, firewall, tool and runtime evidence, and requiring owner review before the route is re-enabled.', retest_acceptance_json='["ARL-KB-013: All observed external destinations and routes for the exact remediated version are represented in the approved inventory.","ARL-KB-013: Authorised in-scope destinations remain reachable through the documented egress path.","ARL-KB-013: Undeclared, unapproved and relevant dynamically redirected destinations are denied or held for explicit review before external transmission.","ARL-KB-013: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and deployment decision are recorded."]', content_digest='aa29c25f10a95b744ab26a6d52d62a6e08fa3e1fa9890934ac866c92a0cea8bc', updated_at='2026-08-06' WHERE entry_id='ARL-KB-013';
UPDATE risk_knowledge_operational_metadata SET automation_status='candidate', customer_validation_status='unvalidated', content_digest='03a0ac78fdfe3eb2ca4bf3a704c7ea35b4b3defed3f46a5f427a6cac53d1435d', updated_at='2026-08-06' WHERE entry_id='ARL-KB-013';
INSERT INTO risk_knowledge_validation_records (id,entry_id,lifecycle_status,knowledge_version,created_at) VALUES ('rkv_013','ARL-KB-013','candidate','ARL-RKA-1.2.0','2026-08-06') ON CONFLICT(entry_id,knowledge_version) DO NOTHING;
INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-013','high','active','2026-10-03','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Long-lived API keys, tokens, cookies or private keys remain active without known owner, scope or rotation plan.","customer_symptom":"Operators cannot reliably identify which API keys, tokens, cookies, private keys or service credentials remain active, who owns them, what they can access, or when they expire.","credible_failure_or_attack":"Unowned, forgotten, over-scoped or long-lived credentials can remain usable after their original purpose ends and may be reused following leakage, personnel change, system drift or compromise.","affected_assets":["API keys, tokens, cookies and private keys","service and workload identities","tool and downstream-system privileges","secret stores and deployment configuration","credential ownership, scope, expiry and rotation records"],"default_severity":"high","severity_rationale":"Incomplete credential inventory can leave active authority unowned or unmonitored. Final severity depends on credential privilege, reachability, lifetime, exposure and compensating controls.","applicability":["tool-using agents"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The boundary between the assessed agent and the credentials or workload identities it can use to access tools, providers and downstream systems.","operational_impact":"If long-lived api keys, tokens, cookies or private keys remain active without known owner, scope or rotation plan, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due":"2026-12-02","change_triggers":["ARL-KB-014 credential, secret-store, workload-identity or service-account change","ARL-KB-014 credential scope, owner, expiry, rotation or revocation-policy change","ARL-KB-014 credential leak, orphaned secret, unexpected use or identity incident","ARL-KB-014 evidence expiry or material scope, environment or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='37d4568c5b8066eb244d3981ef94793544b0ecf18fbb8c24549054de4481b8aa', updated_at='2026-08-06' WHERE id='ARL-KB-014';
UPDATE risk_knowledge_checks SET objective='Determine whether every credential available to the assessed agent has an attributable owner, purpose, scope, storage location, lifecycle state and rotation or expiry policy.', method='Enumerate secret stores, environment references, CI variables, service accounts and observed runtime credential use without exposing secret values. Reconcile discovered credentials against the approved inventory and identify orphaned, duplicate, unused, over-scoped or non-expiring credentials.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-014 assessed system, exact version, environment and credential scope","Authoritative credential or workload-identity inventory with owner, purpose, scope and lifecycle state","Secret-store, environment, CI/CD and runtime references showing which credentials the assessed version can use","Evidence of expiry, rotation, revocation or short-lived issuance where applicable","Tester identity, timestamp and evidence digest"]', pass_condition='ARL-KB-014 passes when all credentials available to the assessed agent are represented in the approved inventory with attributable ownership, necessary scope and documented lifecycle controls, and no tested active credential is orphaned or unexplained.', fail_condition='ARL-KB-014 fails when an active credential available to the assessed system lacks an accountable owner, purpose, known scope, lifecycle state or required rotation/expiry control, or when runtime use cannot be reconciled to the approved inventory.', limitations='This bounded ARL-KB-014 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='9f55fdb91cf5d4543569eed6a3f920b11804153c3440685a6fbf51eac45bf361', updated_at='2026-08-06' WHERE entry_id='ARL-KB-014';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of credential inventory is incomplete and make the remaining risk visible.', recommended_remediation='Assign ownership and expiry, use short-lived workload identity, reduce scopes, revoke unused credentials and monitor anomalous use.', default_owner='Identity and secrets owner', priority='P0', implementation_principles_json='["ARL-KB-014: Give every credential or workload identity an accountable owner, documented purpose and minimum required scope.","ARL-KB-014: Prefer short-lived workload identity and automatic expiry or rotation over long-lived static secrets.","ARL-KB-014: Reconcile secret stores and runtime use against the authoritative inventory and revoke orphaned or unused credentials."]', monitoring='Monitor creation, use, expiry, rotation and revocation of credentials and workload identities; alert the Identity and secrets owner on orphaned credentials, unexpected use, excessive lifetime or scope drift.', containment='Revoke or disable affected credentials, preserve attributable use records, rotate potentially exposed secrets and restore only the minimum required authority after owner review.', retest_acceptance_json='["ARL-KB-014: Every credential available to the exact remediated version is represented in the approved inventory.","ARL-KB-014: Credential owner, purpose, scope and lifecycle state are attributable and current.","ARL-KB-014: Deprecated, revoked, synthetic orphan or otherwise unapproved credentials cannot be used by the assessed runtime.","ARL-KB-014: Reviewer identity, timestamp, assessed version, evidence digest, known limitations and residual-risk decision are recorded."]', content_digest='1b6c58c4c587bfa515ef7a7d86dcf838950df7b819d2987af097a3d3968daaeb', updated_at='2026-08-06' WHERE entry_id='ARL-KB-014';
UPDATE risk_knowledge_operational_metadata SET automation_status='candidate', customer_validation_status='unvalidated', content_digest='4a1fca59bab96e439d9b2acac5db13da86840e5b8e4dc0e02669b6e65c4cb384', updated_at='2026-08-06' WHERE entry_id='ARL-KB-014';
INSERT INTO risk_knowledge_validation_records (id,entry_id,lifecycle_status,knowledge_version,created_at) VALUES ('rkv_014','ARL-KB-014','candidate','ARL-RKA-1.2.0','2026-08-06') ON CONFLICT(entry_id,knowledge_version) DO NOTHING;
INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-014','high','active','2026-10-03','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Persistent context, embeddings and retrieved documents may outlive the project or cross environments and tenants.","customer_symptom":"A user or operator may observe persistent context, embeddings and retrieved documents may outlive the project or cross environments and tenants; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"an external content author, compromised source, malicious user, or unsafe model output can exploit or trigger the condition in persistent context, embeddings and retrieved documents may outlive the project or cross environments and tenants, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tenant-scoped records and object identifiers","service identities, roles and credentials","system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","agent","model context"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["RAG or memory-enabled agents"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"The test crosses the boundary between RAG or memory-enabled agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If persistent context, embeddings and retrieved documents may outlive the project or cross environments and tenants, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due":"2026-12-02","change_triggers":["ARL-KB-015 memory, vector-store, index, namespace, cache, backup or retrieval-source change","ARL-KB-015 retention, deletion, restoration or access-boundary change","ARL-KB-015 cross-environment, cross-tenant, stale-store or unexpected persistence evidence","ARL-KB-015 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='c477e354d0ad83803c0eae3d001cfae1c5c615d64ff90ac777e5ce61275404fb', updated_at='2026-08-06' WHERE id='ARL-KB-015';
UPDATE risk_knowledge_checks SET objective='Determine whether every persistent memory, vector, embedding and retrieval store used by the assessed agent is inventoried with owner, environment, namespace, retention and access boundaries.', method='Inventory persistent memory stores, vector databases, indexes, namespaces, replicas, caches, backups and deletion paths. Map which assessed identities can read or write each store, which environment and tenant or project boundary applies, and whether retention and deletion behaviour are documented.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-015 assessed system, version, environment and scope for Memory and vector stores are untracked","ARL-KB-015 control configuration or source location showing how reduce the likelihood and impact of memory and vector stores are untracked and make the remaining risk visible.","ARL-KB-015 positive and abuse inputs with expected and observed outputs for tenant-scoped records and object identifiers and service identities, roles and credentials","ARL-KB-015 policy, authorization, tool or audit events proving whether the tested memory and vector stores are untracked path executed","ARL-KB-015 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-015 passes when all persistent context and retrieval stores reachable by the assessed version are represented in the governed inventory with attributable ownership, access boundaries, environment, retention and deletion behaviour.', fail_condition='ARL-KB-015 fails when the assessed agent can read from or write to an undeclared persistent store, namespace, replica or backup, or when ownership, environment, retention or deletion behaviour cannot be established with version-bound evidence.', limitations='This bounded ARL-KB-015 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='e8ee229ab832f93f1d6849666cea783c3365bdc51689869dbf849a8444cb288f', updated_at='2026-08-06' WHERE entry_id='ARL-KB-015';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of memory and vector stores are untracked and make the remaining risk visible.', recommended_remediation='Register stores as governed assets, isolate namespaces, restrict write paths, implement retention/deletion and test restoration without cross-tenant data.', default_owner='Data platform owner', priority='P1', implementation_principles_json='["ARL-KB-015: Register every persistent memory, vector, embedding, cache and retrieval store as a governed asset.","ARL-KB-015: Bind stores and namespaces to explicit environments, tenants or projects with least-privilege read and write access.","ARL-KB-015: Define retention, deletion, backup and restoration behaviour and verify retired stores cannot silently remain in use."]', monitoring='For ARL-KB-015, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Data platform owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-015 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-015: “Memory and vector stores are untracked” is no longer reproducible against the exact remediated version.","ARL-KB-015: Authorised in-scope use completes successfully, remains within the documented asset scope for memory and vector stores are untracked, and produces no unintended side effect.","ARL-KB-015: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-015: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='ac4d1d729b2691af71537e0143af74e51ac50926219668151c2e904612e926f2', updated_at='2026-08-06' WHERE entry_id='ARL-KB-015';
UPDATE risk_knowledge_operational_metadata SET automation_status='candidate', customer_validation_status='unvalidated', content_digest='9076a979c831ee283c3d9e641fae6feb614b70a2ec3adfefa120cc2871190b69', updated_at='2026-08-06' WHERE entry_id='ARL-KB-015';
