INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-016','high','active','2026-10-03','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Vulnerable libraries, containers, model loaders, plugins or transitive packages cannot be traced or remediated reliably.","customer_symptom":"A user or operator may observe vulnerable libraries, containers, model loaders, plugins or transitive packages cannot be traced or remediated reliably; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a compromised supplier, dependency maintainer, MCP operator, or deployment pipeline can exploit or trigger the condition in vulnerable libraries, containers, model loaders, plugins or transitive packages cannot be traced or remediated reliably, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["model and dependency artefacts","build, registry and deployment provenance","agent","model context","tools or downstream systems","customer evidence"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["all deployable agents"],"threat_actor_or_failure_source":"a compromised supplier, dependency maintainer, MCP operator, or deployment pipeline","trust_boundary":"The test crosses the boundary between all deployable agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If vulnerable libraries, containers, model loaders, plugins or transitive packages cannot be traced or remediated reliably, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due":"2026-12-02","change_triggers":["ARL-KB-017 dependency, model, adapter, container, plugin, MCP server or build-artifact change","ARL-KB-017 registry, provenance, signing, digest or build-pipeline change","ARL-KB-017 new vulnerability advisory, compromised dependency or supply-chain incident","ARL-KB-017 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='757ab40fc3c8ff934197a48c12a798821a71268e440ccbf1d0c1e0bc41fe213b', updated_at='2026-08-06' WHERE id='ARL-KB-017';
UPDATE risk_knowledge_checks SET objective='Determine whether the assessed system prevents or detects: software and ai dependency bill is missing.', method='Generate and verify SBOM/model inventory data from the exact build; compare it with deployed artefacts and known advisories. Verify model provenance, signed dependency and container digests, MCP-server trust, allowed registries and rejection of executable or unsafe model formats before loading.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-017 assessed system, version, environment and scope for Software and AI dependency bill is missing","ARL-KB-017 control configuration or source location showing how reduce the likelihood and impact of software and ai dependency bill is missing and make the remaining risk visible.","ARL-KB-017 positive and abuse inputs with expected and observed outputs for model and dependency artefacts and build, registry and deployment provenance","ARL-KB-017 policy, authorization, tool or audit events proving whether the tested software and ai dependency bill is missing path executed","ARL-KB-017 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-017 passes only when “Software and AI dependency bill is missing” is not reproducible through the documented abuse cases, the valid workflow remains bounded to model and dependency artefacts and build, registry and deployment provenance, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-017 fails when vulnerable libraries, containers, model loaders, plugins or transitive packages cannot be traced or remediated reliably, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-017 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='6475347ff4fd74dce6165bee56a7507c9b1f11386501a16012e616201a6a08e9', updated_at='2026-08-06' WHERE entry_id='ARL-KB-017';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of software and ai dependency bill is missing and make the remaining risk visible.', recommended_remediation='Produce signed SBOM and model manifests, pin dependencies, remove unused components, monitor advisories and retain rebuild evidence.', default_owner='Software supply-chain owner', priority='P1', implementation_principles_json='["ARL-KB-017: enforce the decision outside the model before any material side effect.","ARL-KB-017: grant the minimum identity, data, tool and network scope required for the approved task.","ARL-KB-017: version configuration, preserve rollback, and fail closed when policy, identity or evidence is unavailable."]', monitoring='For ARL-KB-017, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Software supply-chain owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-017 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-017: “Software and AI dependency bill is missing” is no longer reproducible against the exact remediated version.","ARL-KB-017: Authorised in-scope use completes successfully, remains within the documented asset scope for software and ai dependency bill is missing, and produces no unintended side effect.","ARL-KB-017: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-017: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='ae4c9f0030ac2834babffd2be263e2f96af459824343c542e1d112d67c71c9a8', updated_at='2026-08-06' WHERE entry_id='ARL-KB-017';
UPDATE risk_knowledge_operational_metadata SET automation_status='candidate', customer_validation_status='unvalidated', content_digest='e8a64750cd01b682eb85cfd8733bea61ab24a8532a4f98165e93026fe0434914', updated_at='2026-08-06' WHERE entry_id='ARL-KB-017';
