INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-020','high','active','2026-10-09','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Predictable, long-lived, logged or broadly scoped sessions can be stolen or reused.","customer_symptom":"Users or administrators may observe sessions that remain active after logout, expire too late, survive privilege changes without rotation, or expose session identifiers in insecure storage, URLs or logs.","credible_failure_or_attack":"An attacker who predicts, fixes, obtains or reuses a session identifier can impersonate an authenticated user or retain access after logout, expiry, revocation or a privilege change.","affected_assets":["web control-plane user sessions","session identifiers, cookies and server-side session records","authenticated account and tenant scope","privileged administrative actions and evidence access"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["web control planes"],"threat_actor_or_failure_source":"session fixation, token theft or reuse, insecure cookie or browser storage, weak expiry or invalidation, and session-policy configuration error","trust_boundary":"The boundary between an unauthenticated or superseded session identifier and currently authorised account, tenant and privilege scope on the web control plane.","operational_impact":"If predictable, long-lived, logged or broadly scoped sessions can be stolen or reused, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-09","next_review_due":"2026-12-02","change_triggers":["ARL-KB-021 session-token, cookie, login, logout or session-storage change","ARL-KB-021 session lifetime, rotation, revocation or privilege-change behaviour change","ARL-KB-021 fixation, token leakage, session theft or continued-use incident","ARL-KB-021 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"owner-approved semantic correction; independent practitioner and customer validation required"}', content_digest='1f55ed3f530b7452c0eb115f59c758bd34613251a48d7ed1c98f31812ca77220', updated_at='2026-08-06' WHERE id='ARL-KB-021';
UPDATE risk_knowledge_checks SET objective='Determine whether web control-plane sessions are unpredictable, confidential, correctly scoped and protected against fixation, leakage, replay and continued use after timeout, logout, revocation or privilege changes.', method='Review the owner-approved session policy covering issuance, entropy, cookie/storage flags, idle and absolute lifetime, rotation, concurrent sessions, logout, revocation and role changes. Inspect server-side source/configuration and privacy-safe session metadata without storing raw tokens. With separate written owner authorisation, use synthetic identities in a bounded staging environment to verify valid session use and negative fixation, expired, logged-out, superseded, revoked, replayed and privilege-changed token scenarios; reconcile observed authentication/audit events with the exact assessed version and human-reviewed exceptions.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-021 exact assessed system, version, environment, authenticated identity, tenant and session scope","ARL-KB-021 organisation-approved session policy covering issuance, idle and absolute expiry, secure cookies, storage, rotation, logout, revocation and privilege changes","ARL-KB-021 source or configuration evidence of session creation, cookie attributes, token storage, expiry, rotation and invalidation controls","ARL-KB-021 bounded positive evidence of authorised login, protected session attributes, scoped access and expected session rotation with observed authentication events","ARL-KB-021 bounded negative evidence that fixed, leaked, replayed, expired, logged-out, superseded or revoked session identifiers are rejected, including after privilege changes","ARL-KB-021 observed runtime authentication and session invalidation events tied to the tested identities and exact assessed version","ARL-KB-021 tester and reviewer identity, roles, timestamp, assessed version, scope, exception decision and evidence digest"]', pass_condition='ARL-KB-021 passes only if the approved policy and privacy-safe technical evidence apply to the exact assessed version; valid sessions have bounded scope, protected issuance and transport/storage and documented lifetime; authorised tests demonstrate rotation and timely invalidation; negative tests reject fixed, expired, logged-out, revoked, superseded or privilege-mismatched sessions before protected access; and attributable events, limitations and human review support the decision.', fail_condition='ARL-KB-021 fails or requires review if session identifiers can be fixed, predicted, exposed or reused outside approved lifetime or scope; if logout, revocation, privilege-change rotation or expiry can be bypassed; or if the policy, actual session configuration, bounded denial evidence or attributable review is missing or mismatched to the assessed version.', limitations='This bounded ARL-KB-021 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='4411d5d6080529c46f578e0ba02a588b3121af04804eec436127baf9deccd2cf', updated_at='2026-08-06' WHERE entry_id='ARL-KB-021';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of session tokens are weak or mishandled and make the remaining risk visible.', recommended_remediation='Use strong opaque tokens, secure cookies, server-side revocation, rotation after privilege change and bounded idle/absolute lifetimes.', default_owner='Application security owner', priority='P1', implementation_principles_json='["ARL-KB-021: Generate high-entropy session identifiers and protect them with secure cookie and transport settings.","ARL-KB-021: Rotate sessions after authentication or privilege changes and enforce bounded idle and absolute lifetimes.","ARL-KB-021: Support server-side revocation and prevent session identifiers from appearing in URLs, logs or other unintended evidence."]', monitoring='For ARL-KB-021, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Application security owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-021 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-021: Exact remediated version, approved session policy, cookie/storage/expiry configuration and evidence digest are recorded.","ARL-KB-021: Authorised synthetic sessions function with documented tenant, role, lifetime and rotation behaviour.","ARL-KB-021: Fixed, replayed, expired, logged-out, revoked and privilege-superseded identifiers are rejected with version-bound server events.","ARL-KB-021: Reviewer identity, exception decisions, limitations and exact-retest evidence are recorded."]', content_digest='8158c57c6cfebd1bef29ec2ec149af9ef06abc00a00cf5aeab3833abdce682bc', updated_at='2026-08-06' WHERE entry_id='ARL-KB-021';
UPDATE risk_knowledge_operational_metadata SET automation_status='candidate', customer_validation_status='unvalidated', content_digest='c0502e16d8a1f0ae19ae746a37a2ebcfbe4ca596c6a4f131525f3e002c7f4ece', updated_at='2026-08-06' WHERE entry_id='ARL-KB-021';
INSERT INTO risk_knowledge_validation_records (id,entry_id,lifecycle_status,knowledge_version,created_at) VALUES ('rkv_021','ARL-KB-021','candidate','ARL-RKA-1.2.0','2026-08-06') ON CONFLICT(entry_id,knowledge_version) DO NOTHING;
INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-021','high','active','2026-10-09','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Password reset or recovery can be abused to take over a high-privilege user.","customer_symptom":"A user or operator may observe password reset or recovery can be abused to take over a high-privilege user; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"An attacker can use enumeration, reused recovery codes, expired or altered reset tokens or weak proofing to take over an account despite the normal authentication assurance.","affected_assets":["account identity and recovery records","password-reset tokens and recovery codes","identity provider and privileged access","sessions affected by recovery"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["hosted platforms"],"threat_actor_or_failure_source":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect","trust_boundary":"The test crosses the boundary between hosted platforms and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If password reset or recovery can be abused to take over a high-privilege user, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-09","next_review_due":"2026-12-02","change_triggers":["ARL-KB-022 recovery, reset, identity-proofing, notification or recovery-code change","ARL-KB-022 privileged-account recovery or MFA-recovery policy change","ARL-KB-022 takeover, enumeration, token-reuse or recovery-bypass incident","ARL-KB-022 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"owner-approved semantic correction; independent practitioner validation required"}', content_digest='642ce68cf5a406ca7bd3af7b34b1f18b90b6f99c7402edb6225cf51c4205ebcf', updated_at='2026-08-06' WHERE id='ARL-KB-022';
UPDATE risk_knowledge_checks SET objective='Determine whether account recovery preserves the required authentication assurance and cannot be used to take over a privileged account through enumeration, weak proofing or reusable recovery material.', method='Test account enumeration resistance, recovery-token entropy, expiry and single-use behaviour, identity proofing, notification, recovery-code handling, session invalidation and privileged-account recovery. Verify recovery cannot silently downgrade the normal authentication assurance.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-022 exact assessed system, version, environment and recovery scope","ARL-KB-022 organisation-approved recovery and identity proofing policy with MFA and privileged reset requirements","ARL-KB-022 source or configuration evidence for reset-token expiry, single-use, rate limits, proofing and session invalidation","ARL-KB-022 bounded positive evidence of authorised synthetic recovery preserving identity assurance","ARL-KB-022 bounded negative evidence for account enumeration, expired or reused tokens, weak proofing and MFA downgrade","ARL-KB-022 observed runtime recovery, identity-provider and session invalidation events","ARL-KB-022 tester and reviewer identity, role, timestamp, version and evidence digest"]', pass_condition='Authorised recovery preserves identity proofing and MFA assurance; expired and reused tokens, enumeration and weaker recovery paths cannot grant access, supported by exact-version bounded tests and accountable review.', fail_condition='Account recovery or reset permits enumeration, token replay, weak proofing, MFA downgrade or unauthorised account control, or version-bound evidence is missing.', limitations='This bounded ARL-KB-022 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='14dbbfd11d421290213f3b7c0cd591613e8f1a1d5833727414fd399e801dfa82', updated_at='2026-08-06' WHERE entry_id='ARL-KB-022';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of account recovery bypasses normal assurance and make the remaining risk visible.', recommended_remediation='Harden recovery, rate limit, invalidate sessions after reset, notify the user and require stronger owner recovery procedures.', default_owner='Identity owner', priority='P0', implementation_principles_json='["ARL-KB-022: Recovery must provide assurance appropriate to the account''s privilege and must not become a weaker authentication bypass.","ARL-KB-022: Use high-entropy, short-lived, single-use recovery material and rate-limit recovery attempts.","ARL-KB-022: Notify the account owner and invalidate affected sessions or recovery material after successful reset."]', monitoring='For ARL-KB-022, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Identity owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-022 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-022: “Account recovery bypasses normal assurance” is no longer reproducible against the exact remediated version.","ARL-KB-022: Authorised in-scope use completes successfully, remains within the documented asset scope for account recovery bypasses normal assurance, and produces no unintended side effect.","ARL-KB-022: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-022: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='1344286d22cb3bd89a254c813b6b3135b4087765a69ffc464e99f076603c081e', updated_at='2026-08-06' WHERE entry_id='ARL-KB-022';
UPDATE risk_knowledge_operational_metadata SET automation_status='candidate', customer_validation_status='unvalidated', content_digest='e4c586d45e144215dc20daf19c78ea95810b4f17bd3fb20b5950aac5e5c4f10b', updated_at='2026-08-06' WHERE entry_id='ARL-KB-022';
INSERT INTO risk_knowledge_validation_records (id,entry_id,lifecycle_status,knowledge_version,created_at) VALUES ('rkv_022','ARL-KB-022','candidate','ARL-RKA-1.2.0','2026-08-06') ON CONFLICT(entry_id,knowledge_version) DO NOTHING;
INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-022','critical','active','2026-10-09','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Hidden buttons do not stop a low-privilege caller from invoking privileged APIs directly.","customer_symptom":"A user or operator may observe hidden buttons do not stop a low-privilege caller from invoking privileged apis directly; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"An authenticated low-privilege caller can bypass interface-only restrictions and invoke privileged API routes or service methods directly when server-side authorization is missing, inconsistent or fails open.","affected_assets":["privileged API functions and service methods","role-to-function authorization rules","administrative resources and tenant state","audit records and downstream actions"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["multi-role platforms"],"threat_actor_or_failure_source":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect","trust_boundary":"The boundary between a caller''s authenticated role and server-enforced permission to perform a protected function in the assessed tenant.","operational_impact":"If hidden buttons do not stop a low-privilege caller from invoking privileged apis directly, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-09","next_review_due":"2026-12-02","change_triggers":["ARL-KB-023 role, permission, route, service-method or authorization-policy change","ARL-KB-023 new privileged function or alternate execution path","ARL-KB-023 function-level authorization bypass or fail-open incident","ARL-KB-023 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"owner-approved semantic correction; customer and independent practitioner validation required"}', content_digest='a7e3378cd874fa79b9f231fd519c2a9344e08c2950b63a2b7d9f2d0a9fb6f467', updated_at='2026-08-06' WHERE id='ARL-KB-023';
UPDATE risk_knowledge_checks SET objective='Determine whether every sensitive API and service function enforces the approved role-to-function authorization server-side, including direct calls, alternate methods and policy failures.', method='Replay representative privileged requests as each relevant lower-privilege role and through direct API or service calls, including alternate HTTP methods where applicable. Verify authorization is enforced server-side on every sensitive function and fails closed when policy is missing, stale or unavailable.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-023 exact assessed system, version, environment, tenant, role and protected function scope","ARL-KB-023 organisation-approved role-function authorization matrix with accountable owner and privileged operations","ARL-KB-023 source or configuration evidence of server-side authorization checks and fail-closed policy paths","ARL-KB-023 bounded positive evidence of authorised role performing the approved function with observed policy decision","ARL-KB-023 bounded negative evidence of low-privilege direct API, alternate-method and missing-policy attempts rejected before side effects","ARL-KB-023 observed runtime authorization and downstream audit events proving tested allow and deny outcomes","ARL-KB-023 tester and reviewer identity, role, timestamp, exact version and evidence digest"]', pass_condition='KB-023 passes only when the assessed role-function matrix and source enforcement apply to the exact version, authorised actions work within scope, low-privilege direct/alternate API calls and fail-open variants are denied before any side effect, observed authorization/audit events support each claim, and accountable human review records remaining limitations.', fail_condition='KB-023 fails or requires review when a low-privilege identity invokes a protected function directly or through alternate routes, when server-side authorization is absent or fails open, or when required scoped policy, observed denial and human-review evidence is missing.', limitations='This bounded ARL-KB-023 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='8b0d1f8cf0ab2a3899305684f23a051940bca69be7ebc9a4a12dfe3276ee101e', updated_at='2026-08-06' WHERE entry_id='ARL-KB-023';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of role enforcement exists only in the interface and make the remaining risk visible.', recommended_remediation='Enforce role and object authorization server-side on every route and service method; maintain negative authorization tests.', default_owner='Application security owner', priority='P0', implementation_principles_json='["ARL-KB-023: Enforce role and function authorization server-side on every sensitive route and service method.","ARL-KB-023: Do not treat hidden interface elements or model behaviour as an authorization boundary.","ARL-KB-023: Maintain negative authorization tests for each privileged function and relevant lower-privilege role."]', monitoring='For ARL-KB-023, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Application security owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-023 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-023: The exact revised role-function authorization policy, version and evidence digest are recorded.","ARL-KB-023: Authorised synthetic role-function combinations succeed within the documented tenant and function scope.","ARL-KB-023: Low-privilege, alternate-method and missing-policy bypass variants are denied before side effects, with attributable logs.","ARL-KB-023: An accountable human reviewer records residual exceptions and the exact-retest decision."]', content_digest='6e907d981e8cf0f17155e44c164a37968abd8fd4fff145743af6edc1eb20abb3', updated_at='2026-08-06' WHERE entry_id='ARL-KB-023';
UPDATE risk_knowledge_operational_metadata SET automation_status='candidate', customer_validation_status='unvalidated', content_digest='e4c586d45e144215dc20daf19c78ea95810b4f17bd3fb20b5950aac5e5c4f10b', updated_at='2026-08-06' WHERE entry_id='ARL-KB-023';
INSERT INTO risk_knowledge_validation_records (id,entry_id,lifecycle_status,knowledge_version,created_at) VALUES ('rkv_023','ARL-KB-023','candidate','ARL-RKA-1.2.0','2026-08-06') ON CONFLICT(entry_id,knowledge_version) DO NOTHING;
INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-023','critical','active','2026-10-09','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"A user can read or modify another assessment, project, runtime event, approval or report by changing an identifier.","customer_symptom":"A user or operator may observe a user can read or modify another assessment, project, runtime event, approval or report by changing an identifier; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"An authenticated actor or service identity can access another principal or tenant''s object through direct or indirect identifiers, alternate routes or missing server-side object authorization.","affected_assets":["tenant and workspace-scoped objects","object identifiers and ownership relationships","assessment evidence, approvals and reports","service identities and authorization audit events"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["multi-user platforms"],"threat_actor_or_failure_source":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect","trust_boundary":"Between the authenticated principal and server-enforced tenant, ownership and operation-level authorization for each object access.","operational_impact":"If a user can read or modify another assessment, project, runtime event, approval or report by changing an identifier, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due":"2026-12-02","change_triggers":["ARL-KB-024 object ownership, tenancy, authorization policy or query change","ARL-KB-024 new direct, indirect, export or service-method object route","ARL-KB-024 cross-tenant or cross-user access or fail-open incident","ARL-KB-024 assessed build, scope or evidence expiry change"],"review_status":"candidate semantic correction; customer and independent practitioner validation required"}', content_digest='b87d66e149019f46359d6cc3c4c81b0c34d003e11573b8876e16d1fa178996d5', updated_at='2026-08-06' WHERE id='ARL-KB-024';
UPDATE risk_knowledge_checks SET objective='Determine whether server-side object authorization denies access outside the authenticated actor, tenant, ownership and allowed operation for each read, update, export and delete path.', method='Inspect the owner-approved role/object-operation matrix and server-side query guards. With separate written owner authorization, use synthetic staging identities and objects to exercise bounded positive operations and denied cross-user, cross-tenant, swapped-ID, alternate-route, service-identity and missing-policy variants. Correlate decisions, response payloads, object state and audit trails.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-024 exact assessed system, build version, environment, tenant, workspace, synthetic identities, object types and protected operation scope","ARL-KB-024 organisation-approved actor, role, tenant, ownership and object-operation authorization matrix with accountable policy owner","ARL-KB-024 server-side source or configuration evidence for object-scoped queries, alternate routes, service identities and fail-closed authorization checks","ARL-KB-024 bounded positive evidence of approved synthetic same-tenant object reads, changes, exports and deletes, with observed outputs and object state","ARL-KB-024 bounded negative evidence of cross-user, cross-tenant, identifier-swap, alternate-route and missing-policy requests denied before any data exposure or side effect","ARL-KB-024 observed runtime authorization decisions, response payload checks, before-and-after object state and downstream audit events proving allow and deny outcomes","ARL-KB-024 tester and reviewer identity, roles, timestamps, exact version, evidence digest, exceptions and accountable human decision"]', pass_condition='KB-024 passes only after accountable human review establishes exact-version authorization policy and server enforcement, successful authorized object operations, denied cross-user and cross-tenant direct or alternate access before any payload leakage or side effect, and corroborating runtime/audit evidence with documented limitations.', fail_condition='KB-024 fails or requires review if unauthorized object access, information disclosure, export or mutation occurs; if authorization is UI-only, based on caller-supplied ownership, or fails open through alternate paths; or if exact-version negative tests, runtime observations or human review are missing.', limitations='This bounded ARL-KB-024 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='0a2a2b75c7f0643a5305fe71b855cbf74e4fd31811923af76dcddeac009fc06d', updated_at='2026-08-06' WHERE entry_id='ARL-KB-024';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of object-level authorization can be bypassed and make the remaining risk visible.', recommended_remediation='Resolve objects through tenant-scoped queries, avoid caller-supplied ownership and deny cross-workspace references consistently.', default_owner='Application security owner', priority='P0', implementation_principles_json='["ARL-KB-024: Resolve objects through server-side principal- and tenant-scoped queries.","ARL-KB-024: Never trust caller-supplied ownership, tenant or workspace identifiers as authorization evidence.","ARL-KB-024: Apply object authorization consistently to read, update, delete, export and indirect service paths."]', monitoring='For ARL-KB-024, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Application security owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-024 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-024: Exact revised object-authorization policy, ownership matrix, deployed version and relevant digests are recorded.","ARL-KB-024: Synthetic in-scope object operations succeed with expected outputs and recorded before-and-after state.","ARL-KB-024: Cross-user, cross-tenant, identifier-swap, alternate-route and missing-policy attempts fail closed with no unauthorized payload or side effect and correlated audit records.","ARL-KB-024: An accountable human reviewer records test limitations, exceptions, residual risk and the exact-version retest decision."]', content_digest='baa311c7070f0a8465e422153ca0d003fbbf4753e463803eb7193ef1a9708b59', updated_at='2026-08-06' WHERE entry_id='ARL-KB-024';
UPDATE risk_knowledge_operational_metadata SET automation_status='candidate', customer_validation_status='unvalidated', content_digest='f6ab7ebc90d4bf9d984e2c8bd3e668e95faf0af9c490bf0e19cae782a0c76f11', updated_at='2026-08-06' WHERE entry_id='ARL-KB-024';
INSERT INTO risk_knowledge_validation_records (id,entry_id,lifecycle_status,knowledge_version,created_at) VALUES ('rkv_024','ARL-KB-024','candidate','ARL-RKA-1.2.0','2026-08-06') ON CONFLICT(entry_id,knowledge_version) DO NOTHING;
INSERT INTO risk_knowledge_entry_classification (entry_id,default_severity,active_state,review_date,updated_at) VALUES ('ARL-KB-024','critical','active','2026-10-03','2026-08-06') ON CONFLICT(entry_id) DO UPDATE SET default_severity=excluded.default_severity,active_state=excluded.active_state,review_date=excluded.review_date,updated_at=excluded.updated_at;
UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"An agent can search, summarise, export or modify another customer''s data even when the web application appears isolated.","customer_symptom":"A user or operator may observe an agent can search, summarise, export or modify another customer''s data even when the web application appears isolated; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"A user, compromised agent or mis-scoped service identity can exploit missing or inconsistent tenant binding across vector retrieval, persistent memory, caches, asynchronous jobs, tool calls and exports, exposing another tenant''s records, metadata or actions.","affected_assets":["tenant-scoped documents and vector search indexes","memory stores and cached retrieval results","background job payloads and queues","tool, API and provider service identities","exports, logs and downstream data sinks"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["multi-tenant agents"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"Between the authenticated tenant and the retrieval, memory, cache, asynchronous execution, tool, export and logging layers that must preserve that tenant''s authority.","operational_impact":"If an agent can search, summarise, export or modify another customer''s data even when the web application appears isolated, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due":"2026-12-02","change_triggers":["ARL-KB-025 tenant identity propagation, role, namespace, retrieval or vector index change","ARL-KB-025 cache partition, memory, job, tool, export or log pipeline change","ARL-KB-025 cross-tenant leak, metadata exposure, stale-claim or isolation-bypass incident","ARL-KB-025 assessed scope, build version or evidence expiry change"],"review_status":"candidate semantic correction; independent practitioner and customer validation required"}', content_digest='752f0862cf283216565c21cc7319c845a0dc1de13754c2032e502549abb84138', updated_at='2026-08-06' WHERE id='ARL-KB-025';
UPDATE risk_knowledge_checks SET objective='Determine whether authenticated tenant identity is enforced and fails closed across direct APIs, vector retrieval, memory, caches, asynchronous jobs, tools, exports and logs for the exact assessed build.', method='Review the approved tenant-isolation matrix and version-bound source/configuration, including vector namespace filters, cache partitioning, service identities and async tenant propagation. With separately authorised staging and synthetic Tenant A/B identities and data, execute bounded positive same-tenant and negative cross-tenant scenarios through each applicable path; verify responses, retrieved provenance, downstream effects and attributable audit events.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-025 exact assessed system, version, environment, synthetic tenant and actor identities, retrieval collections, memory stores, cache partitions, background jobs, tools, exports and log scope","ARL-KB-025 organisation-approved tenant and operation isolation policy, permitted data-sharing matrix, identity propagation rules, exceptions and accountable owner","ARL-KB-025 source or configuration evidence for mandatory tenant-scoped retrieval filters, vector namespaces, memory/cache partitioning, job identity context, tool authorization, export/log segregation and fail-closed missing-claim paths","ARL-KB-025 bounded positive evidence of authorised synthetic Tenant A/B requests, searches, memory, cache, jobs, tool calls and exports returning only approved tenant data and state changes","ARL-KB-025 bounded negative evidence of cross-tenant IDs, vector results, memory/cache reuse, asynchronous jobs, tool execution, indirect references, exports, log access and absent-tenant-claim variants denied before data exposure or side effects","ARL-KB-025 observed runtime tenant binding, vector/retrieval filter decisions, item provenance, output, tool and downstream authorization events, before-and-after state and audit records proving allow and deny outcomes","ARL-KB-025 tester and reviewer identity, written authorisation, roles, timestamps, exact assessed version, evidence digest, unsupported paths, exceptions and accountable human decision"]', pass_condition='KB-025 passes only after accountable human review of exact-version source, policy, synthetic same-tenant success and observed cross-tenant denial before metadata or content disclosure or side effects across each applicable retrieval, memory, cache, asynchronous, tool, export and log path, with correlated audit evidence and explicit limits.', fail_condition='KB-025 fails or requires review if tenant identity is omitted or confused, another tenant''s contents or metadata are returned through any path, an unauthorised tool or export action executes, isolation fails open, or exact-version tests, runtime observations or accountable human review are missing.', limitations='This bounded ARL-KB-025 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='97e0d41bc2df59df8be73106289f1dbfc898b10fa5e513e10c482e82adecc2f4', updated_at='2026-08-06' WHERE entry_id='ARL-KB-025';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of tenant isolation fails in retrieval or tools and make the remaining risk visible.', recommended_remediation='Bind tenant identity to every request and data operation, isolate indexes and caches, propagate claims to tools and test every asynchronous path.', default_owner='Security architect', priority='P0', implementation_principles_json='["ARL-KB-025: Bind authoritative tenant identity to every request, retrieval, memory and tool operation.","ARL-KB-025: Isolate indexes, namespaces, caches and asynchronous work by tenant or enforce equivalent server-side policy.","ARL-KB-025: Propagate and revalidate tenant scope across tool calls, exports, background jobs and downstream services."]', monitoring='For ARL-KB-025, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Security architect on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-025 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-025: The exact remediated tenant-isolation policy, identity propagation design, affected data paths, deployed version and signed evidence digests are recorded.","ARL-KB-025: Bounded synthetic same-tenant retrieval, memory, cache, job, tool and export operations succeed with approved outputs and state changes.","ARL-KB-025: Cross-tenant and missing-claim variants are denied before foreign content, metadata or side effects across applicable retrieval, cache, memory, job, tool, export and log paths, with attributable logs.","ARL-KB-025: An accountable human reviewer records unsupported paths, residual exceptions, limitations and the exact-version retest decision."]', content_digest='15b3b5fbae26320094d9336257ca4a1b5353412c2015d7a8ee27b13958a99f14', updated_at='2026-08-06' WHERE entry_id='ARL-KB-025';
UPDATE risk_knowledge_operational_metadata SET automation_status='candidate', customer_validation_status='unvalidated', content_digest='e01e7f7d5afaa1b18d442299a34a82db78e192d8aeef1ffc0b907e96e79423a3', updated_at='2026-08-06' WHERE entry_id='ARL-KB-025';
