UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"One leaked key can operate every project, environment or high-impact tool indefinitely.","customer_symptom":"A user or operator may observe one leaked key can operate every project, environment or high-impact tool indefinitely; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious user, compromised dependency, unsafe model behaviour, or operator error can exploit or trigger the condition in one leaked key can operate every project, environment or high-impact tool indefinitely, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tool endpoints and downstream systems","financial, administrative or state-changing actions","agent","model context","tools or downstream systems","customer evidence"],"default_severity":"high","severity_rationale":"Over-scoped or long-lived API keys can amplify credential compromise. Final severity depends on reachable projects, environments, tools, data, lifetime and revocation controls.","applicability":["API-integrated agents"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The test crosses the boundary between API-integrated agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If one leaked key can operate every project, environment or high-impact tool indefinitely, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due":"2026-12-02","change_triggers":["ARL-KB-027 API-key scope, lifetime, project, environment or permitted-action change","ARL-KB-027 key issuance, storage, rotation or revocation mechanism change","ARL-KB-027 key leakage, cross-project use, excessive-scope use or revocation failure","ARL-KB-027 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='2e8f54cc8cc000c94ff2d2bfe530ce5630412fcb10b147caaab4d3cee30295a7', updated_at='2026-08-06' WHERE id='ARL-KB-027';
UPDATE risk_knowledge_checks SET objective='Determine whether API keys are constrained to the minimum required project, environment, purpose and lifetime and can be promptly revoked.', method='Review key owner, purpose, project/environment scope, permitted actions, issue time, last use, expiry, rotation and revocation. Using synthetic authorised resources, verify a key cannot be reused against unrelated projects, environments or higher-impact actions outside its documented scope.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-027 assessed system, version, environment and scope for API keys have excessive scope and lifetime","ARL-KB-027 control configuration or source location showing how reduce the likelihood and impact of api keys have excessive scope and lifetime and make the remaining risk visible.","ARL-KB-027 positive and abuse inputs with expected and observed outputs for tool endpoints and downstream systems and financial, administrative or state-changing actions","ARL-KB-027 policy, authorization, tool or audit events proving whether the tested api keys have excessive scope and lifetime path executed","ARL-KB-027 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-027 passes only when “API keys have excessive scope and lifetime” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tool endpoints and downstream systems and financial, administrative or state-changing actions, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-027 fails when one leaked key can operate every project, environment or high-impact tool indefinitely, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-027 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='3d1edecdb0484060b55cdbf87fcb6ca33061926dceeffe318ccddcb9f994bd0c', updated_at='2026-08-06' WHERE entry_id='ARL-KB-027';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of api keys have excessive scope and lifetime and make the remaining risk visible.', recommended_remediation='Issue project- and purpose-scoped keys, display secrets once, store only digests, support immediate revocation and prefer short-lived credentials.', default_owner='Platform owner', priority='P0', implementation_principles_json='["ARL-KB-027: Issue project-, environment- and purpose-scoped credentials with the minimum required actions.","ARL-KB-027: Prefer short-lived credentials and support immediate revocation and regular rotation.","ARL-KB-027: Store secrets securely, avoid redisplay where possible and monitor use outside the expected scope."]', monitoring='For ARL-KB-027, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Platform owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-027 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-027: “API keys have excessive scope and lifetime” is no longer reproducible against the exact remediated version.","ARL-KB-027: Authorised in-scope use completes successfully, remains within the documented asset scope for api keys have excessive scope and lifetime, and produces no unintended side effect.","ARL-KB-027: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-027: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='b6f55e54d385fc90065ff34c4c746764ea672673150bbd16e34dff5b78f72460', updated_at='2026-08-06' WHERE entry_id='ARL-KB-027';
