UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Deprovisioning, role changes or workspace removal do not terminate active sessions, keys, approvals or queued actions.","customer_symptom":"A user or operator may observe deprovisioning, role changes or workspace removal do not terminate active sessions, keys, approvals or queued actions; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect can exploit or trigger the condition in deprovisioning, role changes or workspace removal do not terminate active sessions, keys, approvals or queued actions, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tenant-scoped records and object identifiers","service identities, roles and credentials","tool endpoints and downstream systems","financial, administrative or state-changing actions","agent","model context"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["enterprise workspaces"],"threat_actor_or_failure_source":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect","trust_boundary":"The test crosses the boundary between enterprise workspaces and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If deprovisioning, role changes or workspace removal do not terminate active sessions, keys, approvals or queued actions, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due":"2026-12-02","change_triggers":["ARL-KB-028 user lifecycle, role, workspace-membership or deprovisioning change","ARL-KB-028 session, key, approval, queue or delayed-execution revocation change","ARL-KB-028 continued access after role removal or deprovisioning incident","ARL-KB-028 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='7b118d8444fee489af94b52f1e31c6c20baef271ef5b9aa9a8ace99e27f2f7ce', updated_at='2026-08-06' WHERE id='ARL-KB-028';
UPDATE risk_knowledge_checks SET objective='Determine whether user removal and role reduction revoke all derived sessions, keys, approvals and queued authority quickly enough to prevent continued use.', method='Using an owner-authorised test identity, revoke the user or reduce its role while sessions, API credentials, approvals or queued work exist. Verify each derived authority becomes unusable or is re-evaluated before execution.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-028 assessed system, version, environment and scope for Revoked users or stale roles retain access","ARL-KB-028 control configuration or source location showing how reduce the likelihood and impact of revoked users or stale roles retain access and make the remaining risk visible.","ARL-KB-028 positive and abuse inputs with expected and observed outputs for tenant-scoped records and object identifiers and service identities, roles and credentials","ARL-KB-028 policy, authorization, tool or audit events proving whether the tested revoked users or stale roles retain access path executed","ARL-KB-028 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-028 passes only when “Revoked users or stale roles retain access” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tenant-scoped records and object identifiers and service identities, roles and credentials, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-028 fails when deprovisioning, role changes or workspace removal do not terminate active sessions, keys, approvals or queued actions, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-028 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='32f68f6fa087afe942e0d10f8caab005ef70283ad7eef23e221db98bc244f9f0', updated_at='2026-08-06' WHERE entry_id='ARL-KB-028';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of revoked users or stale roles retain access and make the remaining risk visible.', recommended_remediation='Revoke dependent sessions, tokens, approvals and queued authority atomically; record deprovisioning evidence and alert on continued use.', default_owner='Identity lifecycle owner', priority='P0', implementation_principles_json='["ARL-KB-028: Propagate identity and role revocation to sessions, API credentials, approvals and queued authority.","ARL-KB-028: Re-check current authorization before delayed or asynchronous execution.","ARL-KB-028: Record attributable deprovisioning evidence and alert on continued use after revocation."]', monitoring='For ARL-KB-028, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Identity lifecycle owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-028 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-028: “Revoked users or stale roles retain access” is no longer reproducible against the exact remediated version.","ARL-KB-028: Authorised in-scope use completes successfully, remains within the documented asset scope for revoked users or stale roles retain access, and produces no unintended side effect.","ARL-KB-028: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-028: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='8c6a15ae5437adffb3a43b4cb80d1ece0f4ef54e574f307c368aec984c3a7ac0', updated_at='2026-08-06' WHERE entry_id='ARL-KB-028';
