UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Support staff, administrators or agents can impersonate users without scoped purpose, consent, expiry or audit.","customer_symptom":"A user or operator may observe support staff, administrators or agents can impersonate users without scoped purpose, consent, expiry or audit; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious user, compromised dependency, unsafe model behaviour, or operator error can exploit or trigger the condition in support staff, administrators or agents can impersonate users without scoped purpose, consent, expiry or audit, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["agent","model context","tools or downstream systems","customer evidence"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["platforms with support or delegation"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The test crosses the boundary between platforms with support or delegation and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If support staff, administrators or agents can impersonate users without scoped purpose, consent, expiry or audit, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-03","next_review_due":"2026-12-02","change_triggers":["ARL-KB-030 impersonation, delegation, support-session or delegated-approval change","ARL-KB-030 target visibility, privilege ceiling, expiry or termination-control change","ARL-KB-030 delegation abuse, impersonation bypass or unattributable support-action incident","ARL-KB-030 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='520554bd344c8ee338c95b605c995ca07d069a3ab31dda141ba7ee6874cade26', updated_at='2026-08-06' WHERE id='ARL-KB-030';
UPDATE risk_knowledge_checks SET objective='Determine whether impersonation and delegated authority are explicitly scoped to a principal, purpose, target, privilege ceiling and expiry and remain attributable throughout the delegated session.', method='Test impersonation or delegation entry, authorizing principal, reason, target identity, privilege ceiling, session visibility, expiry and termination. Attempt to exceed the delegated scope, change target or continue after termination and verify denial with attributable audit evidence.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-030 assessed system, version, environment and scope for Impersonation and delegation are uncontrolled","ARL-KB-030 control configuration or source location showing how reduce the likelihood and impact of impersonation and delegation are uncontrolled and make the remaining risk visible.","ARL-KB-030 positive and abuse inputs with expected and observed outputs for agent and model context","ARL-KB-030 policy, authorization, tool or audit events proving whether the tested impersonation and delegation are uncontrolled path executed","ARL-KB-030 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-030 passes only when “Impersonation and delegation are uncontrolled” is not reproducible through the documented abuse cases, the valid workflow remains bounded to agent and model context, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-030 fails when support staff, administrators or agents can impersonate users without scoped purpose, consent, expiry or audit, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-030 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='e5fcbbb16c8953a9caa414909e153e9234e98844c1d54473e4d8cd7964e28a2a', updated_at='2026-08-06' WHERE entry_id='ARL-KB-030';
