UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Prompts include secrets, full records or personal data that are not needed for the task.","customer_symptom":"A user or operator may observe prompts include secrets, full records or personal data that are not needed for the task; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"an external content author, compromised source, malicious user, or unsafe model output can exploit or trigger the condition in prompts include secrets, full records or personal data that are not needed for the task, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","model and dependency artefacts","build, registry and deployment provenance","agent","model context"],"default_severity":"high","severity_rationale":"Unnecessary transmission of sensitive data increases disclosure and retention exposure. Final severity depends on data sensitivity, provider handling, reachable recipients and compensating controls.","applicability":["agents handling non-public data"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"The test crosses the boundary between agents handling non-public data and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If prompts include secrets, full records or personal data that are not needed for the task, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-041 model payload, preprocessing, provider or data-field change","ARL-KB-041 purpose, minimisation, redaction or pseudonymisation policy change","ARL-KB-041 sensitive-data disclosure or unexpected provider-retention evidence","ARL-KB-041 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='1fdbc653ad439b76db2c1621fefd9d1714836f93e438442bfc84962e1c5c2668', updated_at='2026-08-06' WHERE id='ARL-KB-041';
UPDATE risk_knowledge_checks SET objective='Determine whether only the minimum data necessary for the stated task is sent to the model or model provider.', method='Trace representative requests from source through preprocessing to the exact model payload. Compare every transmitted field with the documented purpose and minimum task requirements. Identify secrets, identifiers, full records or sensitive attributes that can be removed, redacted or pseudonymised.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-041 assessed system, version, environment and scope for Sensitive data is sent to the model unnecessarily","ARL-KB-041 control configuration or source location showing how reduce the likelihood and impact of sensitive data is sent to the model unnecessarily and make the remaining risk visible.","ARL-KB-041 positive and abuse inputs with expected and observed outputs for system prompt, retrieved context and persistent memory and source documents, messages and generated outputs","ARL-KB-041 policy, authorization, tool or audit events proving whether the tested sensitive data is sent to the model unnecessarily path executed","ARL-KB-041 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-041 passes only when “Sensitive data is sent to the model unnecessarily” is not reproducible through the documented abuse cases, the valid workflow remains bounded to system prompt, retrieved context and persistent memory and source documents, messages and generated outputs, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-041 fails when prompts include secrets, full records or personal data that are not needed for the task, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-041 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='ba6bf6180fe1a30a78776fddd45deca6119b42681b38b6d59947529665657951', updated_at='2026-08-06' WHERE entry_id='ARL-KB-041';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of sensitive data is sent to the model unnecessarily and make the remaining risk visible.', recommended_remediation='Minimise and pseudonymise inputs, redact secrets, use field allowlists and choose provider settings that meet retention and training constraints.', default_owner='Data protection owner', priority='P0', implementation_principles_json='["ARL-KB-041: Minimise model-bound data to fields necessary for the documented purpose.","ARL-KB-041: Remove secrets and unnecessary identifiers and pseudonymise sensitive values where practical.","ARL-KB-041: Make provider retention, training and data-handling configuration explicit and reviewable."]', monitoring='For ARL-KB-041, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Data protection owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-041 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-041: “Sensitive data is sent to the model unnecessarily” is no longer reproducible against the exact remediated version.","ARL-KB-041: Authorised in-scope use completes successfully, remains within the documented asset scope for sensitive data is sent to the model unnecessarily, and produces no unintended side effect.","ARL-KB-041: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-041: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='3e5a2d4fdc006e3d9153b489f3dbb0a7bdf9e812e631c9824e153cc0014f5bf1', updated_at='2026-08-06' WHERE entry_id='ARL-KB-041';
