UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Vector search returns documents the requesting user or agent is not allowed to access.","customer_symptom":"A user or operator may observe vector search returns documents the requesting user or agent is not allowed to access; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"an external content author, compromised source, malicious user, or unsafe model output can exploit or trigger the condition in vector search returns documents the requesting user or agent is not allowed to access, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tenant-scoped records and object identifiers","service identities, roles and credentials","system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","agent","model context"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["RAG systems"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"The test crosses the boundary between RAG systems and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If vector search returns documents the requesting user or agent is not allowed to access, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-043 retrieval, index, metadata-filter, namespace or authorization-policy change","ARL-KB-043 tenant, role, cache or direct-document access-path change","ARL-KB-043 cross-tenant retrieval or unauthorized-document exposure evidence","ARL-KB-043 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='07dd810c60d6bd9591a333d14f2117070906b838f0acb54af3e0089fccfa6296', updated_at='2026-08-06' WHERE id='ARL-KB-043';
UPDATE risk_knowledge_checks SET objective='Determine whether retrieval enforces the requesting principal''s tenant, role and object authorization before documents or metadata enter model context.', method='Seed owner-authorised tenant- and role-specific documents and query them using synthetic identities from different tenants and roles. Inspect retrieval candidates, metadata filtering, caches and final context. Verify unauthorized documents and metadata are excluded before model exposure and remain inaccessible through alternate retrieval paths.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-043 assessed system, version, environment and scope for Retrieval crosses tenant or authorization boundaries","ARL-KB-043 control configuration or source location showing how reduce the likelihood and impact of retrieval crosses tenant or authorization boundaries and make the remaining risk visible.","ARL-KB-043 positive and abuse inputs with expected and observed outputs for tenant-scoped records and object identifiers and service identities, roles and credentials","ARL-KB-043 policy, authorization, tool or audit events proving whether the tested retrieval crosses tenant or authorization boundaries path executed","ARL-KB-043 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-043 passes only when “Retrieval crosses tenant or authorization boundaries” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tenant-scoped records and object identifiers and service identities, roles and credentials, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-043 fails when vector search returns documents the requesting user or agent is not allowed to access, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-043 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='1e73be2044528111b8f683735a4a623b865a202c73ee74a0de74432a5a92b777', updated_at='2026-08-06' WHERE entry_id='ARL-KB-043';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of retrieval crosses tenant or authorization boundaries and make the remaining risk visible.', recommended_remediation='Apply authorization before retrieval and again before response, isolate namespaces, bind metadata to identity and test denied results.', default_owner='Data platform owner', priority='P0', implementation_principles_json='["ARL-KB-043: Apply authoritative identity and tenant authorization before retrieval results enter model context.","ARL-KB-043: Bind document metadata and namespaces to enforceable access-control attributes.","ARL-KB-043: Apply consistent authorization to search, direct lookup, caches and derived retrieval paths."]', monitoring='For ARL-KB-043, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Data platform owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-043 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-043: “Retrieval crosses tenant or authorization boundaries” is no longer reproducible against the exact remediated version.","ARL-KB-043: Authorised in-scope use completes successfully, remains within the documented asset scope for retrieval crosses tenant or authorization boundaries, and produces no unintended side effect.","ARL-KB-043: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-043: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='ba407c50cab6796013f8cc8467921ff4c70849a1b8af2d709978547b32193aee', updated_at='2026-08-06' WHERE entry_id='ARL-KB-043';
