UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Deleting an account leaves prompts, embeddings, summaries, evidence, backups or provider copies behind.","customer_symptom":"A user or operator may observe deleting an account leaves prompts, embeddings, summaries, evidence, backups or provider copies behind; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"an external content author, compromised source, malicious user, or unsafe model output can exploit or trigger the condition in deleting an account leaves prompts, embeddings, summaries, evidence, backups or provider copies behind, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","backups, runtime state and recovery infrastructure","service availability and data integrity","agent","model context"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["agents processing personal data"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"The test crosses the boundary between agents processing personal data and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If deleting an account leaves prompts, embeddings, summaries, evidence, backups or provider copies behind, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-048 retention, deletion, backup, provider-copy or derived-data flow change","ARL-KB-048 new embedding, summary, cache, export or evidence store","ARL-KB-048 deletion failure, retained-derived-data or rights-request incident","ARL-KB-048 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='4693772a0f2f243eb3771f6798cc6f7ff6e9f697b1d2c3f22d9c0d319cacfea2', updated_at='2026-08-06' WHERE id='ARL-KB-048';
UPDATE risk_knowledge_checks SET objective='Determine whether deletion and retention controls cover primary and derived AI data, including prompts, embeddings, summaries, evidence, caches, exports, backups and provider-held copies.', method='Create an owner-authorised synthetic record, allow expected derived artefacts to be produced, then execute the documented deletion workflow. Trace the record across primary storage, derived datasets, embeddings, summaries, caches, exports, backups and provider-held copies and record justified retention limitations.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-048 assessed system, version, environment and scope for Retention and deletion do not cover derived AI data","ARL-KB-048 control configuration or source location showing how reduce the likelihood and impact of retention and deletion do not cover derived ai data and make the remaining risk visible.","ARL-KB-048 positive and abuse inputs with expected and observed outputs for system prompt, retrieved context and persistent memory and source documents, messages and generated outputs","ARL-KB-048 policy, authorization, tool or audit events proving whether the tested retention and deletion do not cover derived ai data path executed","ARL-KB-048 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-048 passes only when “Retention and deletion do not cover derived AI data” is not reproducible through the documented abuse cases, the valid workflow remains bounded to system prompt, retrieved context and persistent memory and source documents, messages and generated outputs, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-048 fails when deleting an account leaves prompts, embeddings, summaries, evidence, backups or provider copies behind, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-048 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='0cfe184e3e79fc258eebe09955b31ea2ccbfb1290ca86623f2dbdd4fcc592884', updated_at='2026-08-06' WHERE entry_id='ARL-KB-048';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of retention and deletion do not cover derived ai data and make the remaining risk visible.', recommended_remediation='Maintain a data map, cascade deletion or justified retention, issue purge receipts, verify backups policy and document unavoidable limitations.', default_owner='Privacy and operations owner', priority='P1', implementation_principles_json='["ARL-KB-048: Maintain a data map connecting source records to derived prompts, embeddings, summaries, evidence and replicas.","ARL-KB-048: Cascade deletion or apply explicit justified retention to every derived location.","ARL-KB-048: Record purge status and unavoidable backup or provider limitations with accountable review."]', monitoring='For ARL-KB-048, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Privacy and operations owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-048 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-048: “Retention and deletion do not cover derived AI data” is no longer reproducible against the exact remediated version.","ARL-KB-048: Authorised in-scope use completes successfully, remains within the documented asset scope for retention and deletion do not cover derived ai data, and produces no unintended side effect.","ARL-KB-048: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-048: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='9977af7172a51a6b23dc75af2f5565720748b5d4af22c5ad87d050c83be95c18', updated_at='2026-08-06' WHERE entry_id='ARL-KB-048';
