UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Repeated queries or combined outputs reveal facts about individuals even when direct identifiers are removed.","customer_symptom":"A user or operator may observe repeated queries or combined outputs reveal facts about individuals even when direct identifiers are removed; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious user, compromised dependency, unsafe model behaviour, or operator error can exploit or trigger the condition in repeated queries or combined outputs reveal facts about individuals even when direct identifiers are removed, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["agent","model context","tools or downstream systems","customer evidence"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["analytics or population-data agents"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The test crosses the boundary between analytics or population-data agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If repeated queries or combined outputs reveal facts about individuals even when direct identifiers are removed, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2