UPDATE risk_knowledge_checks SET objective='Determine whether repeated aggregate or analytical queries can reconstruct, identify or infer sensitive facts about individuals beyond the approved privacy boundary.', method='Using owner-authorised synthetic or approved population data, test small cohorts, overlapping aggregates, repeated queries and auxiliary information for reconstruction, differencing or membership inference. Measure whether query budgets, minimum cohort rules or other privacy controls prevent cumulative disclosure.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-052 assessed system, version, environment and scope for Aggregates enable re-identification or inference","ARL-KB-052 control configuration or source location showing how reduce the likelihood and impact of aggregates enable re-identification or inference and make the remaining risk visible.","ARL-KB-052 positive and abuse inputs with expected and observed outputs for agent and model context","ARL-KB-052 policy, authorization, tool or audit events proving whether the tested aggregates enable re-identification or inference path executed","ARL-KB-052 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-052 passes only when “Aggregates enable re-identification or inference” is not reproducible through the documented abuse cases, the valid workflow remains bounded to agent and model context, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-052 fails when repeated queries or combined outputs reveal facts about individuals even when direct identifiers are removed, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-052 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='a9f109695d0c64aad965ea1b50a24e416d43f6c4227c19d2c0cd2d44e2ff2827', updated_at='2026-08-06' WHERE entry_id='ARL-KB-052';
