UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"The model supplies attacker-controlled account IDs, amounts, paths or destinations that the tool trusts.","customer_symptom":"A user or operator may observe the model supplies attacker-controlled account ids, amounts, paths or destinations that the tool trusts; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious user, compromised dependency, unsafe model behaviour, or operator error can exploit or trigger the condition in the model supplies attacker-controlled account ids, amounts, paths or destinations that the tool trusts, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tool endpoints and downstream systems","financial, administrative or state-changing actions","model and dependency artefacts","build, registry and deployment provenance","agent","model context"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["agents invoking state-changing tools"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The test crosses the boundary between agents invoking state-changing tools and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If the model supplies attacker-controlled account ids, amounts, paths or destinations that the tool trusts, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-055 tool schema, parameter, authorization or business-rule change","ARL-KB-055 new state-changing parameter, destination or object-reference path","ARL-KB-055 malformed-parameter, ownership-bypass or business-rule abuse evidence","ARL-KB-055 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='4e76d79a9a2e9e777b2cf45ff8ce67c4970c2b01bd70c02f91003618592f7340', updated_at='2026-08-06' WHERE id='ARL-KB-055';
UPDATE risk_knowledge_checks SET objective='Determine whether state-changing tools independently validate model-supplied parameters against authenticated identity, ownership, allowed ranges, destinations and business constraints before side effects.', method='Bypass normal model orchestration and submit owner-authorised synthetic tool calls with missing, malformed, out-of-range, cross-tenant, unauthorized-destination and policy-violating parameters directly at the tool boundary. Verify typed validation and authorization occur inside the tool service before any side effect.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-055 assessed system, version, environment and scope for Tool parameters are not independently validated","ARL-KB-055 control configuration or source location showing how reduce the likelihood and impact of tool parameters are not independently validated and make the remaining risk visible.","ARL-KB-055 positive and abuse inputs with expected and observed outputs for tool endpoints and downstream systems and financial, administrative or state-changing actions","ARL-KB-055 policy, authorization, tool or audit events proving whether the tested tool parameters are not independently validated path executed","ARL-KB-055 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-055 passes only when “Tool parameters are not independently validated” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tool endpoints and downstream systems and financial, administrative or state-changing actions, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-055 fails when the model supplies attacker-controlled account ids, amounts, paths or destinations that the tool trusts, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-055 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='659bea34e7928b0a666f771fb6a04e56e60a7a346fdf611852b2552d3b5095d2', updated_at='2026-08-06' WHERE entry_id='ARL-KB-055';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of tool parameters are not independently validated and make the remaining risk visible.', recommended_remediation='Validate typed schemas, identity, ownership, range, destination and business constraints inside the tool service before side effects.', default_owner='Tool service owner', priority='P0', implementation_principles_json='["ARL-KB-055: Validate typed schemas and business constraints inside the tool service, not in model reasoning alone.","ARL-KB-055: Re-check authenticated identity, ownership, destination and allowed ranges at execution time.","ARL-KB-055: Fail closed on missing, ambiguous or policy-violating parameters before state change."]', monitoring='For ARL-KB-055, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Tool service owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-055 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-055: “Tool parameters are not independently validated” is no longer reproducible against the exact remediated version.","ARL-KB-055: Authorised in-scope use completes successfully, remains within the documented asset scope for tool parameters are not independently validated, and produces no unintended side effect.","ARL-KB-055: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-055: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='5528068f1e9f13f4319b8ccf92a37b67df9984ed0f3ddf7515cac430ec680fa0', updated_at='2026-08-06' WHERE entry_id='ARL-KB-055';
