UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Agent-controlled values are concatenated into shell commands, scripts, templates or dynamic evaluation.","customer_symptom":"A user or operator may observe agent-controlled values are concatenated into shell commands, scripts, templates or dynamic evaluation; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious user, compromised dependency, unsafe model behaviour, or operator error can exploit or trigger the condition in agent-controlled values are concatenated into shell commands, scripts, templates or dynamic evaluation, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tool endpoints and downstream systems","financial, administrative or state-changing actions","agent","model context","tools or downstream systems","customer evidence"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["code, shell or automation agents"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The test crosses the boundary between code, shell or automation agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If agent-controlled values are concatenated into shell commands, scripts, templates or dynamic evaluation, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-056 command, shell, template, script or dynamic-evaluation path change","ARL-KB-056 new executable tool, interpreter or model-controlled argument path","ARL-KB-056 command injection, template injection or arbitrary-code execution evidence","ARL-KB-056 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='69cafca2ad089d310cf8ad892a923b93e170608f514aa301b5be587c9ede9eb3', updated_at='2026-08-06' WHERE id='ARL-KB-056';
