UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Path traversal, symlinks or archive extraction let the agent read or overwrite secrets and system files.","customer_symptom":"A user or operator may observe path traversal, symlinks or archive extraction let the agent read or overwrite secrets and system files; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"an external content author, compromised source, malicious user, or unsafe model output can exploit or trigger the condition in path traversal, symlinks or archive extraction let the agent read or overwrite secrets and system files, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","tool endpoints and downstream systems","financial, administrative or state-changing actions","agent","model context"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["filesystem-capable agents"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"The test crosses the boundary between filesystem-capable agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If path traversal, symlinks or archive extraction let the agent read or overwrite secrets and system files, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-058 filesystem tool, path resolver, archive handler or sandbox-boundary change","ARL-KB-058 new file operation, mount, symlink or extraction capability","ARL-KB-058 traversal, link escape, race-condition or archive-breakout evidence","ARL-KB-058 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='025e5b00ba4f910174c983df5b17c59603f03cfcfa52507f0dac386692eede46', updated_at='2026-08-06' WHERE id='ARL-KB-058';
