UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"The agent runs packages or code with host, network, secret or production access.","customer_symptom":"A user or operator may observe the agent runs packages or code with host, network, secret or production access; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect can exploit or trigger the condition in the agent runs packages or code with host, network, secret or production access, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tenant-scoped records and object identifiers","service identities, roles and credentials","tool endpoints and downstream systems","financial, administrative or state-changing actions","agent","model context"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["coding and execution agents"],"threat_actor_or_failure_source":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect","trust_boundary":"The test crosses the boundary between coding and execution agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If the agent runs packages or code with host, network, secret or production access, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-059 sandbox runtime, container, VM, code-execution or isolation-policy change","ARL-KB-059 network, secret, filesystem or resource-limit change","ARL-KB-059 sandbox escape, ambient-secret access or uncontrolled execution evidence","ARL-KB-059 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='470b27d5980fff9a5eb706a3da5ad9174141acb4c70710c4fb874f181c1e837d', updated_at='2026-08-06' WHERE id='ARL-KB-059';
UPDATE risk_knowledge_checks SET objective='Determine whether generated or agent-selected code executes inside a bounded disposable environment without ambient host, secret, network or production authority.', method='In an owner-authorised sandbox, execute controlled samples that attempt filesystem escape, process spawning, network access, secret discovery, persistence and resource exhaustion. Verify isolation, resource limits, termination, blocked egress and absence of ambient production credentials.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-059 assessed system, version, environment and scope for Generated code executes without containment","ARL-KB-059 control configuration or source location showing how reduce the likelihood and impact of generated code executes without containment and make the remaining risk visible.","ARL-KB-059 positive and abuse inputs with expected and observed outputs for tenant-scoped records and object identifiers and service identities, roles and credentials","ARL-KB-059 policy, authorization, tool or audit events proving whether the tested generated code executes without containment path executed","ARL-KB-059 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-059 passes only when “Generated code executes without containment” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tenant-scoped records and object identifiers and service identities, roles and credentials, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-059 fails when the agent runs packages or code with host, network, secret or production access, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-059 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='43b1a0e27b60b5d6d589f706c33e45256002041d3952fcd2f982b6110bdaf983', updated_at='2026-08-06' WHERE entry_id='ARL-KB-059';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of generated code executes without containment and make the remaining risk visible.', recommended_remediation='Use disposable sandboxes, no ambient secrets, blocked egress by default, strict resource limits, signed inputs and human approval for promotion.', default_owner='Sandbox platform owner', priority='P0', implementation_principles_json='["ARL-KB-059: Execute generated code in disposable least-privilege sandboxes rather than on the application host.","ARL-KB-059: Remove ambient secrets and deny network access by default unless explicitly required.","ARL-KB-059: Enforce strict CPU, memory, process, filesystem and execution-time limits and require governed promotion to production."]', monitoring='For ARL-KB-059, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Sandbox platform owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-059 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-059: “Generated code executes without containment” is no longer reproducible against the exact remediated version.","ARL-KB-059: Authorised in-scope use completes successfully, remains within the documented asset scope for generated code executes without containment, and produces no unintended side effect.","ARL-KB-059: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-059: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='3ef477ec12fdb73582ad6535c8856c9d0f7c124e0e9224a31f1dc5d0f20a6a2f', updated_at='2026-08-06' WHERE entry_id='ARL-KB-059';
