ed data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-060 MCP server identity, transport, package, version or deployment change","ARL-KB-060 tool catalogue, schema, credential or trust-policy change","ARL-KB-060 server replacement, provenance failure or unexpected catalogue-drift evidence","ARL-KB-060 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='f21ef447f50971edc2d4fe611b85d7a38b11bb75cb19bc0472dbdeeabbdb9a36', updated_at='2026-08-06' WHERE id='ARL-KB-060';
