UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"A valid approval for one target, amount, destination or tool authorises a changed transaction.","customer_symptom":"A user or operator may observe a valid approval for one target, amount, destination or tool authorises a changed transaction; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect can exploit or trigger the condition in a valid approval for one target, amount, destination or tool authorises a changed transaction, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tenant-scoped records and object identifiers","service identities, roles and credentials","tool endpoints and downstream systems","financial, administrative or state-changing actions","agent","model context"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["agents requiring human approval"],"threat_actor_or_failure_source":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect","trust_boundary":"The test crosses the boundary between agents requiring human approval and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If a valid approval for one target, amount, destination or tool authorises a changed transaction, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-066 approval payload, canonicalisation, tool parameter or policy-binding change","ARL-KB-066 new material transaction field or hidden execution default","ARL-KB-066 approval-substitution, parameter-mutation or binding-bypass evidence","ARL-KB-066 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='6091a0c302629b5f17efda7daaf6bcbccc8f8ee482ad81f23d3c69b440b99575', updated_at='2026-08-06' WHERE id='ARL-KB-066';
UPDATE risk_knowledge_checks SET objective='Determine whether an approval is cryptographically or deterministically bound to the exact material action that was reviewed.', method='Issue an approval for a synthetic action, then independently mutate each material field before execution, including tool identity, environment, target, amount or value, currency, destination, policy version, hidden defaults and canonical representations. Verify every material mutation invalidates the approval.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-066 assessed system, version, environment and scope for Approval is not bound to the exact action","ARL-KB-066 control configuration or source location showing how reduce the likelihood and impact of approval is not bound to the exact action and make the remaining risk visible.","ARL-KB-066 positive and abuse inputs with expected and observed outputs for tenant-scoped records and object identifiers and service identities, roles and credentials","ARL-KB-066 policy, authorization, tool or audit events proving whether the tested approval is not bound to the exact action path executed","ARL-KB-066 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-066 passes only when “Approval is not bound to the exact action” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tenant-scoped records and object identifiers and service identities, roles and credentials, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-066 fails when a valid approval for one target, amount, destination or tool authorises a changed transaction, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-066 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='9cd58570a0ea3089505dca8b611d5f17d7bb2a1c7fe8921226c9b2a3b2b24766', updated_at='2026-08-06' WHERE entry_id='ARL-KB-066';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of approval is not bound to the exact action and make the remaining risk visible.', recommended_remediation='Hash and bind tool, environment, target, value, currency, destination, policy version and validity period into the approval.', default_owner='Approval service owner', priority='P0', implementation_principles_json='["ARL-KB-066: Bind approvals to a canonical representation of every material execution parameter.","ARL-KB-066: Include tool, environment, target, value, destination, policy version and validity period where applicable.","ARL-KB-066: Reject execution when canonical action data differs from the action that was approved."]', monitoring='For ARL-KB-066, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Approval service owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-066 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-066: “Approval is not bound to the exact action” is no longer reproducible against the exact remediated version.","ARL-KB-066: Authorised in-scope use completes successfully, remains within the documented asset scope for approval is not bound to the exact action, and produces no unintended side effect.","ARL-KB-066: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-066: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='2fd416044d6be489d7892ccd526b7b662fb1ba8b0c1e00110550e37127d92298', updated_at='2026-08-06' WHERE entry_id='ARL-KB-066';
