UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"A captured token can authorise the same or another action multiple times.","customer_symptom":"A user or operator may observe a captured token can authorise the same or another action multiple times; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect can exploit or trigger the condition in a captured token can authorise the same or another action multiple times, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tenant-scoped records and object identifiers","service identities, roles and credentials","tool endpoints and downstream systems","financial, administrative or state-changing actions","agent","model context"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["agents requiring human approval"],"threat_actor_or_failure_source":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect","trust_boundary":"The test crosses the boundary between agents requiring human approval and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If a captured token can authorise the same or another action multiple times, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-067 approval token, consumption, idempotency or replay-control change","ARL-KB-067 new asynchronous or concurrent approval-consumption path","ARL-KB-067 replay, duplicate-consumption or expired-approval execution evidence","ARL-KB-067 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='c71c19f075c609d1504a2f6759549b7a91cc893ba523e4298eec0c9430034abf', updated_at='2026-08-06' WHERE id='ARL-KB-067';
UPDATE risk_knowledge_checks SET objective='Determine whether an approval can be consumed no more than the permitted number of times and cannot be replayed after use, revocation or expiry.', method='Issue one owner-authorised synthetic approval and attempt sequential and concurrent execution using the same token and varied request identifiers. Verify atomic single-use consumption, expiry, revocation and idempotency prevent duplicate or later reuse.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-067 assessed system, version, environment and scope for Approval can be replayed","ARL-KB-067 control configuration or source location showing how reduce the likelihood and impact of approval can be replayed and make the remaining risk visible.","ARL-KB-067 positive and abuse inputs with expected and observed outputs for tenant-scoped records and object identifiers and service identities, roles and credentials","ARL-KB-067 policy, authorization, tool or audit events proving whether the tested approval can be replayed path executed","ARL-KB-067 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-067 passes only when “Approval can be replayed” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tenant-scoped records and object identifiers and service identities, roles and credentials, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-067 fails when a captured token can authorise the same or another action multiple times, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-067 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='2360fe7885c4ee38084f41491d9d16363c7ec444267e920cd7d0fdb7785e2859', updated_at='2026-08-06' WHERE entry_id='ARL-KB-067';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of approval can be replayed and make the remaining risk visible.', recommended_remediation='Store only token digests, enforce single-use atomic consumption, bind idempotency and reject consumed, revoked or expired approvals.', default_owner='Approval service owner', priority='P0', implementation_principles_json='["ARL-KB-067: Enforce atomic single-use consumption for approvals that authorize one execution.","ARL-KB-067: Reject consumed, revoked and expired approvals at the execution boundary.","ARL-KB-067: Bind approval consumption to transaction idempotency so concurrency cannot duplicate the side effect."]', monitoring='For ARL-KB-067, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Approval service owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-067 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-067: “Approval can be replayed” is no longer reproducible against the exact remediated version.","ARL-KB-067: Authorised in-scope use completes successfully, remains within the documented asset scope for approval can be replayed, and produces no unintended side effect.","ARL-KB-067: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-067: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='8956f71d3d0c65a4dc108dd0f386dd9aa5574b40c18869fb0c92d8fed4d6e681', updated_at='2026-08-06' WHERE entry_id='ARL-KB-067';
