UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"The human sees a friendly summary while the actual target, destination, permissions or side effects differ.","customer_symptom":"A user or operator may observe the human sees a friendly summary while the actual target, destination, permissions or side effects differ; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect can exploit or trigger the condition in the human sees a friendly summary while the actual target, destination, permissions or side effects differ, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tenant-scoped records and object identifiers","service identities, roles and credentials","system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","agent","model context"],"default_severity":"high","severity_rationale":"Misleading approval context can cause a human to authorise an action they did not intend. Final severity depends on the action''s impact, reversibility and the authority available after approval.","applicability":["human-in-the-loop agents"],"threat_actor_or_failure_source":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect","trust_boundary":"The test crosses the boundary between human-in-the-loop agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If the human sees a friendly summary while the actual target, destination, permissions or side effects differ, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-072 approval UI, canonical action or parameter-presentation change","ARL-KB-072 new high-impact action or hidden execution default","ARL-KB-072 misleading approval display, confusable value or post-approval mutation evidence","ARL-KB-072 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='1bd5268992e299c87426cb3645122d88aa828263adc6ee6dcdabbec48c67447a', updated_at='2026-08-06' WHERE id='ARL-KB-072';
UPDATE risk_knowledge_checks SET objective='Determine whether the human approver sees the same material action, target, destination, permissions and consequences that will actually be executed.', method='Compare the approval interface, authoritative approval object and final canonical execution request. Test truncated values, Unicode confusables, hidden defaults, misleading summaries and last-second parameter changes. Verify material execution data cannot differ from what the approver reviewed.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-072 assessed system, version, environment and scope for Approval interface hides material context","ARL-KB-072 control configuration or source location showing how reduce the likelihood and impact of approval interface hides material context and make the remaining risk visible.","ARL-KB-072 positive and abuse inputs with expected and observed outputs for tenant-scoped records and object identifiers and service identities, roles and credentials","ARL-KB-072 policy, authorization, tool or audit events proving whether the tested approval interface hides material context path executed","ARL-KB-072 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-072 passes only when “Approval interface hides material context” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tenant-scoped records and object identifiers and service identities, roles and credentials, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-072 fails when the human sees a friendly summary while the actual target, destination, permissions or side effects differ, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-072 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='f2462c0d050fed51cb29ec82b8b2a2e0141c92306b65a6d75adbd14ddcf0a139', updated_at='2026-08-06' WHERE entry_id='ARL-KB-072';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of approval interface hides material context and make the remaining risk visible.', recommended_remediation='Display the exact canonical action and consequences, require deliberate confirmation, freeze parameters and show trusted source identity.', default_owner='Product security owner', priority='P0', implementation_principles_json='["ARL-KB-072: Display the exact canonical material action rather than a model-generated summary alone.","ARL-KB-072: Make consequential targets, values, permissions and side effects explicit before confirmation.","ARL-KB-072: Freeze approved parameters and require fresh approval after any material change."]', monitoring='For ARL-KB-072, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Product security owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-072 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-072: “Approval interface hides material context” is no longer reproducible against the exact remediated version.","ARL-KB-072: Authorised in-scope use completes successfully, remains within the documented asset scope for approval interface hides material context, and produces no unintended side effect.","ARL-KB-072: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-072: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='d4382a6e9fc0070ec125a9c705b5089552da7f4d67d2864bd06b9e40b883b7af', updated_at='2026-08-06' WHERE entry_id='ARL-KB-072';
