UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Weights or endpoints may be substituted, tampered with or obtained from an untrusted publisher.","customer_symptom":"A user or operator may observe weights or endpoints may be substituted, tampered with or obtained from an untrusted publisher; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious user, compromised dependency, unsafe model behaviour, or operator error can exploit or trigger the condition in weights or endpoints may be substituted, tampered with or obtained from an untrusted publisher, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["model and dependency artefacts","build, registry and deployment provenance","agent","model context","tools or downstream systems","customer evidence"],"default_severity":"high","severity_rationale":"Unverifiable model provenance creates substitution and tampering risk. Final severity depends on model privileges, deployment exposure, downstream authority and whether untrusted model bytes can execute code.","applicability":["self-hosted or imported models"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The test crosses the boundary between self-hosted or imported models and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If weights or endpoints may be substituted, tampered with or obtained from an untrusted publisher, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-073 model publisher, artifact, endpoint, revision or provenance mechanism change","ARL-KB-073 model replacement, import or provider-version change","ARL-KB-073 digest mismatch, substituted model or provenance-failure evidence","ARL-KB-073 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='6f716278a754d929f7a2e6aabfbbac0ecd9d124ec7eeb8254f9eb08ec4bdba12', updated_at='2026-08-06' WHERE id='ARL-KB-073';
UPDATE risk_knowledge_checks SET objective='Determine whether the exact deployed model can be traced to an approved publisher, immutable version or digest and documented transfer or acquisition path.', method='For the exact assessed model, verify publisher or provider origin, licence where relevant, immutable revision or digest, available signature or attestation evidence and the transfer path into deployment. Compare the recorded provenance with the exact deployed bytes or provider revision and test rejection of an unapproved substitute.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-073 assessed system, version, environment and scope for Model provenance cannot be verified","ARL-KB-073 control configuration or source location showing how reduce the likelihood and impact of model provenance cannot be verified and make the remaining risk visible.","ARL-KB-073 positive and abuse inputs with expected and observed outputs for model and dependency artefacts and build, registry and deployment provenance","ARL-KB-073 policy, authorization, tool or audit events proving whether the tested model provenance cannot be verified path executed","ARL-KB-073 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-073 passes only when “Model provenance cannot be verified” is not reproducible through the documented abuse cases, the valid workflow remains bounded to model and dependency artefacts and build, registry and deployment provenance, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-073 fails when weights or endpoints may be substituted, tampered with or obtained from an untrusted publisher, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-073 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='230acca3c1cf849bb1090bae4ed6f9fbf0c26dcdb548c4db3de1b7f9ebcc4593', updated_at='2026-08-06' WHERE entry_id='ARL-KB-073';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of model provenance cannot be verified and make the remaining risk visible.', recommended_remediation='Use approved publishers, immutable manifests, digest verification, quarantined intake and provenance records tied to deployment.', default_owner='ML supply-chain owner', priority='P0', implementation_principles_json='["ARL-KB-073: Record approved model publisher, source, immutable revision or digest and acquisition path.","ARL-KB-073: Verify model identity against the exact artifact or provider revision used in deployment.","ARL-KB-073: Quarantine and review model artifacts whose provenance cannot be established."]', monitoring='For ARL-KB-073, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the ML supply-chain owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-073 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-073: “Model provenance cannot be verified” is no longer reproducible against the exact remediated version.","ARL-KB-073: Authorised in-scope use completes successfully, remains within the documented asset scope for model provenance cannot be verified, and produces no unintended side effect.","ARL-KB-073: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-073: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='90d6c6c38ac38b66a40ed8f2699fb334eb3420792321308a1196221003fd2b8d', updated_at='2026-08-06' WHERE entry_id='ARL-KB-073';
