UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Libraries, frameworks or model servers expose exploitable flaws in the agent''s actual attack surface.","customer_symptom":"A user or operator may observe libraries, frameworks or model servers expose exploitable flaws in the agent''s actual attack surface; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a compromised supplier, dependency maintainer, MCP operator, or deployment pipeline can exploit or trigger the condition in libraries, frameworks or model servers expose exploitable flaws in the agent''s actual attack surface, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["model and dependency artefacts","build, registry and deployment provenance","agent","model context","tools or downstream systems","customer evidence"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["all deployable agents"],"threat_actor_or_failure_source":"a compromised supplier, dependency maintainer, MCP operator, or deployment pipeline","trust_boundary":"The test crosses the boundary between all deployable agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If libraries, frameworks or model servers expose exploitable flaws in the agent''s actual attack surface, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-076 dependency, framework, model-server or runtime-package change","ARL-KB-076 new advisory affecting a deployed component","ARL-KB-076 reachable vulnerable path, exploit evidence or compensating-control failure","ARL-KB-076 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='0957bfe9d547f7411f8f0dc7b70665cb0088376208383bf1f4879e87481464e3', updated_at='2026-08-06' WHERE id='ARL-KB-076';
