nsupported by reproducible evidence.', limitations='This bounded ARL-KB-076 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='b77a6f97a6706a103fdfdcb6bf45a481df1f8a765bc5175c7f623ba7ab350201', updated_at='2026-08-06' WHERE entry_id='ARL-KB-076';
