UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"A typosquatted, compromised or overprivileged extension steals secrets or alters agent behaviour.","customer_symptom":"A user or operator may observe a typosquatted, compromised or overprivileged extension steals secrets or alters agent behaviour; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect can exploit or trigger the condition in a typosquatted, compromised or overprivileged extension steals secrets or alters agent behaviour, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tool endpoints and downstream systems","financial, administrative or state-changing actions","model and dependency artefacts","build, registry and deployment provenance","agent","model context"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["extensible agents"],"threat_actor_or_failure_source":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect","trust_boundary":"The test crosses the boundary between extensible agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If a typosquatted, compromised or overprivileged extension steals secrets or alters agent behaviour, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-077 plugin, package, MCP dependency, registry or publisher change","ARL-KB-077 install script, permission, update-channel or network-authority change","ARL-KB-077 malicious dependency, typosquat, publisher compromise or integrity-failure evidence","ARL-KB-077 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='2971ec9a976ad41e77e14f8b7f36213d0abb377d0ae82a7cf527b6c850eb4327', updated_at='2026-08-06' WHERE id='ARL-KB-077';
UPDATE risk_knowledge_checks SET objective='Determine whether plugins, packages and MCP dependencies come from approved trustworthy sources and cannot gain unreviewed permissions, install-time execution or network access.', method='Review exact publisher identity, package integrity, registry source, install scripts, requested permissions, network behaviour and update channel. In quarantine, inspect or test a synthetic untrusted dependency and verify it cannot enter the trusted runtime or gain authority without explicit approval.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-077 assessed system, version, environment and scope for Plugin, package or MCP dependency is malicious","ARL-KB-077 control configuration or source location showing how reduce the likelihood and impact of plugin, package or mcp dependency is malicious and make the remaining risk visible.","ARL-KB-077 positive and abuse inputs with expected and observed outputs for tool endpoints and downstream systems and financial, administrative or state-changing actions","ARL-KB-077 policy, authorization, tool or audit events proving whether the tested plugin, package or mcp dependency is malicious path executed","ARL-KB-077 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-077 passes only when “Plugin, package or MCP dependency is malicious” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tool endpoints and downstream systems and financial, administrative or state-changing actions, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-077 fails when a typosquatted, compromised or overprivileged extension steals secrets or alters agent behaviour, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-077 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='f42c6c5d3fd942b9aead894ab7964cf74d102dab96c693aa8e6779e828ef2f18', updated_at='2026-08-06' WHERE entry_id='ARL-KB-077';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of plugin, package or mcp dependency is malicious and make the remaining risk visible.', recommended_remediation='Use approved registries, lockfiles, signatures where available, permission review, sandboxed installation and rapid revocation.', default_owner='Supply-chain owner', priority='P0', implementation_principles_json='["ARL-KB-077: Restrict extensions to approved registries, publishers and integrity-verified artifacts.","ARL-KB-077: Review install scripts, runtime permissions and network authority before trusted use.","ARL-KB-077: Quarantine new or changed extensions and support rapid revocation of compromised dependencies."]', monitoring='For ARL-KB-077, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Supply-chain owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-077 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-077: “Plugin, package or MCP dependency is malicious” is no longer reproducible against the exact remediated version.","ARL-KB-077: Authorised in-scope use completes successfully, remains within the documented asset scope for plugin, package or mcp dependency is malicious, and produces no unintended side effect.","ARL-KB-077: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-077: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='26b6c742ef306e2f4b338a56adde912677d035763f00ebe95819dfe1192865dd', updated_at='2026-08-06' WHERE entry_id='ARL-KB-077';
