UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Agent output rendered as HTML or Markdown executes script or unsafe links in a user''s browser.","customer_symptom":"A user or operator may observe agent output rendered as html or markdown executes script or unsafe links in a user''s browser; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"an external content author, compromised source, malicious user, or unsafe model output can exploit or trigger the condition in agent output rendered as html or markdown executes script or unsafe links in a user''s browser, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["agent","model context","tools or downstream systems","customer evidence"],"default_severity":"critical","severity_rationale":"Default critical rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["web-displayed agent output"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"The test crosses the boundary between web-displayed agent output and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If agent output rendered as html or markdown executes script or unsafe links in a user''s browser, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-082 renderer, Markdown engine, sanitiser, CSP or export-path change","ARL-KB-082 new rich-content or web-display surface","ARL-KB-082 stored, reflected or DOM execution evidence from agent content","ARL-KB-082 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='ea1916b739d5b26c3e76c5a3c67de8adfbddf403e489536f4d823ccf5c4d7cb2', updated_at='2026-08-06' WHERE id='ARL-KB-082';
UPDATE risk_knowledge_checks SET objective='Determine whether generated or retrieved agent content can execute active browser content when rendered as HTML, Markdown, rich text or exported web content.', method='Using an authorised test environment, submit reflected and stored XSS payloads through prompts, retrieval sources and tool results, then exercise every relevant renderer and export path. Verify context-aware encoding, sanitisation and browser policy prevent script execution, unsafe event handlers and dangerous URL schemes.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-082 assessed system, version, environment and scope for Generated content causes cross-site scripting","ARL-KB-082 control configuration or source location showing how reduce the likelihood and impact of generated content causes cross-site scripting and make the remaining risk visible.","ARL-KB-082 positive and abuse inputs with expected and observed outputs for agent and model context","ARL-KB-082 policy, authorization, tool or audit events proving whether the tested generated content causes cross-site scripting path executed","ARL-KB-082 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-082 passes only when “Generated content causes cross-site scripting” is not reproducible through the documented abuse cases, the valid workflow remains bounded to agent and model context, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-082 fails when agent output rendered as html or markdown executes script or unsafe links in a user''s browser, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-082 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='d0b9e491af251e4cd568853305bdec205142469fd31be4481b0bf7ded5d336b4', updated_at='2026-08-06' WHERE entry_id='ARL-KB-082';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of generated content causes cross-site scripting and make the remaining risk visible.', recommended_remediation='Escape by output context, sanitise allowed markup, use restrictive CSP and avoid dangerous HTML insertion APIs.', default_owner='Web security owner', priority='P0', implementation_principles_json='["ARL-KB-082: Encode generated content according to the exact browser output context.","ARL-KB-082: Sanitize allowed rich content with a narrow explicit policy rather than trusting model output.","ARL-KB-082: Use restrictive browser security controls and avoid unsafe HTML insertion APIs."]', monitoring='For ARL-KB-082, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Web security owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-082 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-082: “Generated content causes cross-site scripting” is no longer reproducible against the exact remediated version.","ARL-KB-082: Authorised in-scope use completes successfully, remains within the documented asset scope for generated content causes cross-site scripting, and produces no unintended side effect.","ARL-KB-082: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-082: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='e260701eea4949aff3822a10898cf00afb334e6a7b4163f7158be72457670b7d', updated_at='2026-08-06' WHERE entry_id='ARL-KB-082';
