UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Newlines and control characters alter headers, forge audit events or split downstream messages.","customer_symptom":"A user or operator may observe newlines and control characters alter headers, forge audit events or split downstream messages; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"an external content author, compromised source, malicious user, or unsafe model output can exploit or trigger the condition in newlines and control characters alter headers, forge audit events or split downstream messages, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","agent","model context","tools or downstream systems","customer evidence"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["agents creating messages or logs"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"The test crosses the boundary between agents creating messages or logs and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If newlines and control characters alter headers, forge audit events or split downstream messages, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-084 email, logging, protocol encoder or message-format change","ARL-KB-084 new generated header, message or structured-log field","ARL-KB-084 CRLF, log-forging or protocol-splitting evidence","ARL-KB-084 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='2201092f51c24c8cca59a8a4f7b2722a30bdc48aa4bb9489573d67bae6bc4b2f', updated_at='2026-08-06' WHERE id='ARL-KB-084';
UPDATE risk_knowledge_checks SET objective='Determine whether generated text can alter email headers, log structure, protocol framing or downstream records through control characters, delimiters or message splitting.', method='Test CRLF, delimiter injection, structured-log breaking, header splitting and protocol-specific control characters through every generated field that reaches messages, logs or protocol encoders. Verify safe libraries and field validation preserve record and message boundaries.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-084 assessed system, version, environment and scope for Generated text injects email, log or protocol fields","ARL-KB-084 control configuration or source location showing how reduce the likelihood and impact of generated text injects email, log or protocol fields and make the remaining risk visible.","ARL-KB-084 positive and abuse inputs with expected and observed outputs for system prompt, retrieved context and persistent memory and source documents, messages and generated outputs","ARL-KB-084 policy, authorization, tool or audit events proving whether the tested generated text injects email, log or protocol fields path executed","ARL-KB-084 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-084 passes only when “Generated text injects email, log or protocol fields” is not reproducible through the documented abuse cases, the valid workflow remains bounded to system prompt, retrieved context and persistent memory and source documents, messages and generated outputs, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-084 fails when newlines and control characters alter headers, forge audit events or split downstream messages, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-084 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='fa167a297d3ade6266d14aaa87e76780050ae3d799a38c4bbca3ecea676f46e6', updated_at='2026-08-06' WHERE entry_id='ARL-KB-084';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of generated text injects email, log or protocol fields and make the remaining risk visible.', recommended_remediation='Use safe libraries, structured logging, field length limits and reject control characters where they are not valid data.', default_owner='Application security owner', priority='P1', implementation_principles_json='["ARL-KB-084: Use structured message, logging and protocol libraries rather than manual string concatenation.","ARL-KB-084: Reject or encode control characters that are invalid for the destination field.","ARL-KB-084: Apply field-length and structural validation before generated content reaches downstream protocols."]', monitoring='For ARL-KB-084, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Application security owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-084 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-084: “Generated text injects email, log or protocol fields” is no longer reproducible against the exact remediated version.","ARL-KB-084: Authorised in-scope use completes successfully, remains within the documented asset scope for generated text injects email, log or protocol fields, and produces no unintended side effect.","ARL-KB-084: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-084: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='8b1513e4f9fadcae6108ea2eef51cbfdbf8273668dd2a3df14ebd3d74dde2212', updated_at='2026-08-06' WHERE entry_id='ARL-KB-084';
