exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-086 high-impact use case, domain, model, source or review-workflow change","ARL-KB-086 new autonomous or consequential decision authority","ARL-KB-086 harmful misinformation, unsupported recommendation or reviewer-bypass evidence","ARL-KB-086 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='46b253ca973cb23ffbe7fa965d0ef9f2840208a75c39570dca75183294835e6b', updated_at='2026-08-06' WHERE id='ARL-KB-086';
