UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Observability duplicates sensitive prompts, credentials, tool arguments and model outputs into broadly accessible systems.","customer_symptom":"A user or operator may observe observability duplicates sensitive prompts, credentials, tool arguments and model outputs into broadly accessible systems; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"an external content author, compromised source, malicious user, or unsafe model output can exploit or trigger the condition in observability duplicates sensitive prompts, credentials, tool arguments and model outputs into broadly accessible systems, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tenant-scoped records and object identifiers","service identities, roles and credentials","system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","tool endpoints and downstream systems","financial, administrative or state-changing actions"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["all production agents"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"The test crosses the boundary between all production agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If observability duplicates sensitive prompts, credentials, tool arguments and model outputs into broadly accessible systems, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-089 logging, tracing, crash-reporting, telemetry or support-export change","ARL-KB-089 new sensitive field, tool argument or observability sink","ARL-KB-089 secret, credential or personal-data leakage into observability evidence","ARL-KB-089 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='42b8f566f59fc750de2dab639385fbbfe22cf366c5053c398df8ac16aef66640', updated_at='2026-08-06' WHERE id='ARL-KB-089';
UPDATE risk_knowledge_checks SET objective='Determine whether observability systems collect or expose secrets, credentials, personal data or sensitive agent content beyond the minimum evidence required for operations and assurance.', method='Sample representative logs, traces, metrics, crash reports and support exports from the assessed production-equivalent system. Trace prompts, credentials, tool arguments, retrieved content and model outputs into observability pipelines and verify source redaction, field allowlists, access controls and retention prevent unnecessary sensitive-data duplication.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-089 assessed system, version, environment and scope for Logs and traces contain secrets or personal data","ARL-KB-089 control configuration or source location showing how reduce the likelihood and impact of logs and traces contain secrets or personal data and make the remaining risk visible.","ARL-KB-089 positive and abuse inputs with expected and observed outputs for tenant-scoped records and object identifiers and service identities, roles and credentials","ARL-KB-089 policy, authorization, tool or audit events proving whether the tested logs and traces contain secrets or personal data path executed","ARL-KB-089 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-089 passes only when “Logs and traces contain secrets or personal data” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tenant-scoped records and object identifiers and service identities, roles and credentials, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-089 fails when observability duplicates sensitive prompts, credentials, tool arguments and model outputs into broadly accessible systems, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-089 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='3e52fe248133faa83db6b1d55084cfc66a89f78b3d98d717cd677c7a4d5d79b3', updated_at='2026-08-06' WHERE entry_id='ARL-KB-089';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of logs and traces contain secrets or personal data and make the remaining risk visible.', recommended_remediation='Redact at source, use structured allowlists, separate security evidence from raw content, limit access and apply retention.', default_owner='Observability and privacy owner', priority='P1', implementation_principles_json='["ARL-KB-089: Minimise observability content and redact sensitive fields at the earliest practical boundary.","ARL-KB-089: Prefer structured allowlists of evidence fields over logging raw prompts, payloads or tool results.","ARL-KB-089: Restrict access and retention for logs, traces and support exports according to data sensitivity."]', monitoring='For ARL-KB-089, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Observability and privacy owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-089 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-089: “Logs and traces contain secrets or personal data” is no longer reproducible against the exact remediated version.","ARL-KB-089: Authorised in-scope use completes successfully, remains within the documented asset scope for logs and traces contain secrets or personal data, and produces no unintended side effect.","ARL-KB-089: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-089: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='fb8c83cf008cd5f09e8bf63ef13bfbd1654d7acc2dd6b62d27f9713c82c2882c', updated_at='2026-08-06' WHERE entry_id='ARL-KB-089';
