UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Valid credentials are used for unusual volumes, destinations, tool sequences or values without detection.","customer_symptom":"A user or operator may observe valid credentials are used for unusual volumes, destinations, tool sequences or values without detection; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious user, compromised dependency, unsafe model behaviour, or operator error can exploit or trigger the condition in valid credentials are used for unusual volumes, destinations, tool sequences or values without detection, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tool endpoints and downstream systems","financial, administrative or state-changing actions","agent","model context","tools or downstream systems","customer evidence"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["internet-facing or high-value agents"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The test crosses the boundary between internet-facing or high-value agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If valid credentials are used for unusual volumes, destinations, tool sequences or values without detection, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-093 abuse-detection, baseline, rate-limit or anomaly-model change","ARL-KB-093 new high-value action, public exposure or destination type","ARL-KB-093 credential abuse, anomalous sequence, volume or value-splitting evidence","ARL-KB-093 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='3ea66f04f16ebc6b8c91ed1557ab299d7d7099e767e56fee4ad23d5fb179a47e', updated_at='2026-08-06' WHERE id='ARL-KB-093';
UPDATE risk_knowledge_checks SET objective='Determine whether valid credentials used in abnormal volumes, destinations, sequences or transaction patterns produce detectable and reviewable abuse signals.', method='In a controlled environment, replay credential misuse, bulk access, low-and-slow probing, unusual tool sequences, value splitting and new-destination patterns. Verify detection considers identity, volume, sequence, destination and value context and that meaningful anomalies produce bounded response or review signals.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-093 assessed system, version, environment and scope for Abuse and anomaly detection is absent","ARL-KB-093 control configuration or source location showing how reduce the likelihood and impact of abuse and anomaly detection is absent and make the remaining risk visible.","ARL-KB-093 positive and abuse inputs with expected and observed outputs for tool endpoints and downstream systems and financial, administrative or state-changing actions","ARL-KB-093 policy, authorization, tool or audit events proving whether the tested abuse and anomaly detection is absent path executed","ARL-KB-093 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-093 passes only when “Abuse and anomaly detection is absent” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tool endpoints and downstream systems and financial, administrative or state-changing actions, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-093 fails when valid credentials are used for unusual volumes, destinations, tool sequences or values without detection, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-093 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='b5f2fe13992daeed01e7aa4a335d3f39c4484c31c47888248aab2444970c15de', updated_at='2026-08-06' WHERE entry_id='ARL-KB-093';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of abuse and anomaly detection is absent and make the remaining risk visible.', recommended_remediation='Baseline expected behaviour, detect risk signals across identity and tools, rate limit, step up controls and preserve reviewable evidence.', default_owner='Security operations owner', priority='P1', implementation_principles_json='["ARL-KB-093: Establish expected behavioural baselines appropriate to identity, tool and transaction context.","ARL-KB-093: Correlate abuse signals across identity, volume, destination, sequence and value rather than relying on one indicator.","ARL-KB-093: Apply proportional rate limits, step-up controls or review while preserving attributable evidence."]', monitoring='For ARL-KB-093, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Security operations owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-093 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-093: “Abuse and anomaly detection is absent” is no longer reproducible against the exact remediated version.","ARL-KB-093: Authorised in-scope use completes successfully, remains within the documented asset scope for abuse and anomaly detection is absent, and produces no unintended side effect.","ARL-KB-093: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-093: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='f2cf2a40ec8056ccde9c28ca62494e86b4c9a7e62f0d2b0b44ec423a7e8ad30e', updated_at='2026-08-06' WHERE entry_id='ARL-KB-093';
