UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Monitoring captures more user data than necessary and retains it longer than the security purpose requires.","customer_symptom":"A user or operator may observe monitoring captures more user data than necessary and retains it longer than the security purpose requires; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious user, compromised dependency, unsafe model behaviour, or operator error can exploit or trigger the condition in monitoring captures more user data than necessary and retains it longer than the security purpose requires, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["agent","model context","tools or downstream systems","customer evidence"],"default_severity":"medium","severity_rationale":"Default medium rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["all production agents"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The test crosses the boundary between all production agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If monitoring captures more user data than necessary and retains it longer than the security purpose requires, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-094 telemetry schema, destination, access or retention change","ARL-KB-094 new observability source or collection purpose","ARL-KB-094 unnecessary sensitive telemetry or excessive-retention evidence","ARL-KB-094 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='17f1d0db9b0a66c7b2481e68926544d013630ef589ba5cf24efd227440b16732', updated_at='2026-08-06' WHERE id='ARL-KB-094';
UPDATE risk_knowledge_checks SET objective='Determine whether telemetry collection and retention are limited to the minimum data necessary for documented security, reliability and incident-response purposes.', method='Inventory telemetry fields, destinations, access roles and retention periods and map each item to a documented security or operational question. Identify raw content that could be replaced by hashes, counts or bounded metadata and verify exceptional sensitive access is explicit, attributable and time-limited.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-094 assessed system, version, environment and scope for Telemetry collection is unbounded","ARL-KB-094 control configuration or source location showing how reduce the likelihood and impact of telemetry collection is unbounded and make the remaining risk visible.","ARL-KB-094 positive and abuse inputs with expected and observed outputs for agent and model context","ARL-KB-094 policy, authorization, tool or audit events proving whether the tested telemetry collection is unbounded path executed","ARL-KB-094 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-094 passes only when “Telemetry collection is unbounded” is not reproducible through the documented abuse cases, the valid workflow remains bounded to agent and model context, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-094 fails when monitoring captures more user data than necessary and retains it longer than the security purpose requires, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-094 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='0ad93097b11acc53e4c6aa2787e8ba1ac1cddfd506f3964c7ba7dd7695874cd0', updated_at='2026-08-06' WHERE entry_id='ARL-KB-094';
