eview_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-096 planner, delegation, retry, timeout or termination-policy change","ARL-KB-096 new autonomous or multi-agent recursion path","ARL-KB-096 infinite loop, repeated-state or duplicate-side-effect evidence","ARL-KB-096 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='fbba38152e0ac287f2c393cff802833dd97839213096712a3ea9abeb67a7e39b', updated_at='2026-08-06' WHERE id='ARL-KB-096';
