UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Model, vector, identity or tool failure leads to unsafe fallback, corrupted work or prolonged outage.","customer_symptom":"A user or operator may observe model, vector, identity or tool failure leads to unsafe fallback, corrupted work or prolonged outage; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect can exploit or trigger the condition in model, vector, identity or tool failure leads to unsafe fallback, corrupted work or prolonged outage, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["tenant-scoped records and object identifiers","service identities, roles and credentials","tool endpoints and downstream systems","financial, administrative or state-changing actions","model and dependency artefacts","build, registry and deployment provenance"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["production agents"],"threat_actor_or_failure_source":"a malicious or mistaken authenticated user, compromised agent identity, or authorization defect","trust_boundary":"The test crosses the boundary between production agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If model, vector, identity or tool failure leads to unsafe fallback, corrupted work or prolonged outage, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-097 critical dependency, timeout, fallback, queue or recovery-path change","ARL-KB-097 new provider, identity, vector, storage or tool dependency","ARL-KB-097 unsafe fallback, corrupted recovery or prolonged-outage evidence","ARL-KB-097 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='7a7df611ebe48ecee6ded05fefd89efc1258871785e0d2cda1fe340bae568dc2', updated_at='2026-08-06' WHERE id='ARL-KB-097';
UPDATE risk_knowledge_checks SET objective='Determine whether failure of a critical model, identity, vector, storage or tool dependency produces a safe, recoverable state rather than unsafe fallback, corrupted work or uncontrolled execution.', method='In a controlled environment, disable each critical third-party dependency individually and exercise representative workflows. Observe timeout handling, denial, queueing, fallback, user communication, recovery and evidence consistency. Verify consequential operations fail closed or degrade only through explicitly approved safe paths.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-097 assessed system, version, environment and scope for Third-party outage has no safe behaviour","ARL-KB-097 control configuration or source location showing how reduce the likelihood and impact of third-party outage has no safe behaviour and make the remaining risk visible.","ARL-KB-097 positive and abuse inputs with expected and observed outputs for tenant-scoped records and object identifiers and service identities, roles and credentials","ARL-KB-097 policy, authorization, tool or audit events proving whether the tested third-party outage has no safe behaviour path executed","ARL-KB-097 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-097 passes only when “Third-party outage has no safe behaviour” is not reproducible through the documented abuse cases, the valid workflow remains bounded to tenant-scoped records and object identifiers and service identities, roles and credentials, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-097 fails when model, vector, identity or tool failure leads to unsafe fallback, corrupted work or prolonged outage, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-097 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='b1ce4d38332b4afbefcfebf762127263433eb13870ced88d181d7730445da68e', updated_at='2026-08-06' WHERE entry_id='ARL-KB-097';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of third-party outage has no safe behaviour and make the remaining risk visible.', recommended_remediation='Define safe degradation, dependency timeouts, tested fallback or fail-closed behaviour, status communication and recovery objectives.', default_owner='Service reliability owner', priority='P1', implementation_principles_json='["ARL-KB-097: Define explicit safe-degradation or fail-closed behaviour for each critical external dependency.","ARL-KB-097: Use bounded timeouts, circuit breakers and tested recovery paths rather than uncontrolled retries.","ARL-KB-097: Preserve consistent evidence and clear operator or user communication during dependency failure and recovery."]', monitoring='For ARL-KB-097, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Service reliability owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-097 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-097: “Third-party outage has no safe behaviour” is no longer reproducible against the exact remediated version.","ARL-KB-097: Authorised in-scope use completes successfully, remains within the documented asset scope for third-party outage has no safe behaviour, and produces no unintended side effect.","ARL-KB-097: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-097: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='888a2f56bb6752456ce57e57fd08ddc401ea19c0f862b32e062056a6827dabcc', updated_at='2026-08-06' WHERE entry_id='ARL-KB-097';
