UPDATE risk_knowledge_checks SET objective='Determine whether concurrent plans, approvals or tool actions can violate shared-state invariants, overwrite newer data or bypass quotas and authorization decisions.', method='Using owner-authorised synthetic workflows, run concurrent updates, approvals, quota consumption and tool actions against shared state. Verify transactions, locking or compare-and-swap semantics preserve documented invariants and that retries remain idempotent after conflicts.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-098 assessed system, version, environment and scope for Concurrency produces inconsistent state","ARL-KB-098 control configuration or source location showing how reduce the likelihood and impact of concurrency produces inconsistent state and make the remaining risk visible.","ARL-KB-098 positive and abuse inputs with expected and observed outputs for agent and model context","ARL-KB-098 policy, authorization, tool or audit events proving whether the tested concurrency produces inconsistent state path executed","ARL-KB-098 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-098 passes only when “Concurrency produces inconsistent state” is not reproducible through the documented abuse cases, the valid workflow remains bounded to agent and model context, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-098 fails when parallel plans read stale data, overwrite each other or bypass limits and approvals, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-098 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='05e58122a5fb49d425833f9d08862a5b84cca98b84e7495eadda26888a6c09d4', updated_at='2026-08-06' WHERE entry_id='ARL-KB-098';
