UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Prompts, policies, vector indexes, approvals, remediation and audit records cannot be restored consistently.","customer_symptom":"A user or operator may observe prompts, policies, vector indexes, approvals, remediation and audit records cannot be restored consistently; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"an external content author, compromised source, malicious user, or unsafe model output can exploit or trigger the condition in prompts, policies, vector indexes, approvals, remediation and audit records cannot be restored consistently, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["system prompt, retrieved context and persistent memory","source documents, messages and generated outputs","backups, runtime state and recovery infrastructure","service availability and data integrity","agent","model context"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["stateful hosted platforms"],"threat_actor_or_failure_source":"an external content author, compromised source, malicious user, or unsafe model output","trust_boundary":"The test crosses the boundary between stateful hosted platforms and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If prompts, policies, vector indexes, approvals, remediation and audit records cannot be restored consistently, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-103 authoritative store, backup scope, retention or restoration-process change","ARL-KB-103 new persistent AI state or evidence store","ARL-KB-103 backup integrity, incomplete restore or recovery-consistency failure","ARL-KB-103 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='9562f299cff8b300e8180383c3499db73ca6bb65f3f24445716c95ed0fa11a50', updated_at='2026-08-06' WHERE id='ARL-KB-103';
UPDATE risk_knowledge_checks SET objective='Determine whether authoritative AI state and assurance evidence can be restored consistently after loss or corruption.', method='Verify scheduled backup records, integrity manifests, encryption, retention and access controls for representative authoritative stores including policies, vector indexes, approvals, remediation state and audit evidence. Perform an isolated restoration and verify relationships, versions and integrity remain consistent.', check_types_json='["declared-control review","observed-control inspection","negative or abuse test","evidence review"]', required_evidence_json='["ARL-KB-103 assessed system, version, environment and scope for Backups do not protect AI state and evidence","ARL-KB-103 control configuration or source location showing how reduce the likelihood and impact of backups do not protect ai state and evidence and make the remaining risk visible.","ARL-KB-103 positive and abuse inputs with expected and observed outputs for system prompt, retrieved context and persistent memory and source documents, messages and generated outputs","ARL-KB-103 policy, authorization, tool or audit events proving whether the tested backups do not protect ai state and evidence path executed","ARL-KB-103 tester identity, role, timestamp and evidence digest"]', pass_condition='ARL-KB-103 passes only when “Backups do not protect AI state and evidence” is not reproducible through the documented abuse cases, the valid workflow remains bounded to system prompt, retrieved context and persistent memory and source documents, messages and generated outputs, denial occurs before side effects, and version-bound observed evidence matches the expected decision.', fail_condition='ARL-KB-103 fails when prompts, policies, vector indexes, approvals, remediation and audit records cannot be restored consistently, or when the relevant control is declaration-only, bypassable, fail-open, applied after a side effect, evaluated under the wrong identity or tenant, or unsupported by reproducible evidence.', limitations='This bounded ARL-KB-103 test does not prove absence of undiscovered paths, future regressions or risks outside the stated identities, inputs, environment and version.', content_digest='aa1a0c87b5b4d566e921a7ce82fc0fb9da5c51541dd4e6111fb81c34fb75570e', updated_at='2026-08-06' WHERE entry_id='ARL-KB-103';
UPDATE risk_knowledge_solutions SET control_objective='Reduce the likelihood and impact of backups do not protect ai state and evidence and make the remaining risk visible.', recommended_remediation='Back up authoritative stores with tested manifests, retention and access controls; rehearse isolated restore and document recovery objectives.', default_owner='Operations owner', priority='P1', implementation_principles_json='["ARL-KB-103: Back up authoritative AI state and assurance evidence according to documented recovery objectives.","ARL-KB-103: Protect backup integrity, confidentiality and version relationships.","ARL-KB-103: Rehearse isolated restoration and verify recovered state before it is trusted operationally."]', monitoring='For ARL-KB-103, record policy version and digest, actor, target, decision, denial reason and side-effect outcome; alert the Operations owner on bypass attempts, configuration drift, repeated denials and missing decision evidence.', containment='Contain ARL-KB-103 by disabling the affected capability or route, revoking scoped authority, isolating impacted identities and data, preserving versioned evidence, and requiring owner approval before re-enablement.', retest_acceptance_json='["ARL-KB-103: “Backups do not protect AI state and evidence” is no longer reproducible against the exact remediated version.","ARL-KB-103: Authorised in-scope use completes successfully, remains within the documented asset scope for backups do not protect ai state and evidence, and produces no unintended side effect.","ARL-KB-103: Unauthorised identity, boundary-crossing, malformed-input, replay and relevant bypass variants are denied before execution, with the expected policy and downstream events recorded.","ARL-KB-103: Reviewer identity, timestamp, deployed version, evidence digest, known limitations and rollback decision are recorded."]', content_digest='f45840c3862b96f1258cd4835d81b989ce4a7a41571f7ec8ad3c49f7c4a3b112', updated_at='2026-08-06' WHERE entry_id='ARL-KB-103';
