UPDATE risk_knowledge_entries SET knowledge_version='ARL-RKA-1.2.0', problem_json='{"statement":"Reports describe risk but do not create accountable work, so critical issues remain open indefinitely.","customer_symptom":"A user or operator may observe reports describe risk but do not create accountable work, so critical issues remain open indefinitely; the resulting symptom can include an unauthorized action, incorrect output, unavailable service, data exposure or an evidence gap within this control''s stated scope.","credible_failure_or_attack":"a malicious user, compromised dependency, unsafe model behaviour, or operator error can exploit or trigger the condition in reports describe risk but do not create accountable work, so critical issues remain open indefinitely, crossing the assessed trust boundary before an external enforcement point detects or blocks it.","affected_assets":["agent","model context","tools or downstream systems","customer evidence"],"default_severity":"high","severity_rationale":"Default high rating reflects the potential impact before customer-specific exposure, likelihood, reversibility and compensating controls are verified.","applicability":["assessed agents"],"threat_actor_or_failure_source":"a malicious user, compromised dependency, unsafe model behaviour, or operator error","trust_boundary":"The test crosses the boundary between assessed agents and the identities, data sources, tools, providers or operators that can influence or receive its actions.","operational_impact":"If reports describe risk but do not create accountable work, so critical issues remain open indefinitely, accountable operators may need to stop affected actions, investigate scoped data and identities, restore integrity, notify stakeholders where required, and hold deployment until retest evidence exists."}', review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-105 finding workflow, ownership, due-date, exception or closure-evidence change","ARL-KB-105 new severity class or remediation-governance process","ARL-KB-105 unowned, overdue or evidence-free finding-closure evidence","ARL-KB-105 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"expert-authored candidate; customer and independent practitioner validation required"}', content_digest='6f5af76f0f578a879ac0e9cf18c9e59d26211d9c461c8a38136fd955e2484971', updated_at='2026-08-06' WHERE id='ARL-KB-105';
